102	/// An unelaborated region left as a stub by the coarse structural scan
103	/// (verbatim from the v4 §22 sketch).
104	///
105	/// Unneeded regions remain opaque: only their exact byte range, content hash,
106	/// and coarse classification are known until demand-driven parsing (v4 §23)
107	/// elaborates them because they are visible, edited, queried, referenced,
108	/// required by a pass, or needed by a backend.
109	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
110	pub struct OpaqueBlock {
111	    /// Exact byte range of the block within its source basis (v4 §22).
112	    pub range: SourceRange,
113	    /// Content hash of the raw bytes, for structural sharing and change
114	    /// detection across revisions (v4 §9, §22).
115	    pub hash: ContentHash,
116	    /// Cheap classification produced by the coarse scan (v4 §22).
117	    pub coarse_kind: CoarseKind,
118	}
119	
120	/// Coarse classification produced by the first structural pass (v4 §22 list).
121	///
122	/// SHAPE PROVISIONAL — the variant set transcribes the §22 bullet list
123	/// ("files and document roots, block boundaries, headings, lists, fences,
124	/// directives, embedded language regions, resource references"); Phase 1
125	/// grammar work (ADR pending, v4 §119) may reshape it freely.
126	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
127	#[serde(rename_all = "kebab-case")]
128	pub enum CoarseKind {
129	    /// A file or document root (v4 §22).
130	    DocumentRoot,
131	    /// A heading block (v4 §22).
132	    Heading,
133	    /// An ordinary paragraph-like block (v4 §22 "block boundaries").
134	    ParagraphLike,
135	    /// A list block (v4 §22).
136	    List,
137	    /// A fenced block (v4 §22).
138	    Fence,
139	    /// A directive block (v4 §22).
140	    Directive,
141	    /// An embedded-language region (v4 §9, §22).
142	    EmbeddedLanguage,
143	    /// A resource reference (v4 §22).
144	    ResourceReference,
145	    /// Anything the coarse scan cannot classify; error-tolerant parsing never
146	    /// rejects bytes (v4 §9 "invalid syntax").
147	    Unknown,
148	}
  1	//! Pure incremental queries over an explicit Workspace Basis.
  2	//!
  3	//! Every expensive pure computation is a revisioned query over a declared
  4	//! [`WorkspaceBasis`]: deterministic for that basis, immutable, memoized,
  5	//! dependency-tracked, and replayable from frozen Jurisdiction inputs
  6	//! (v4 §24). External resolution is deliberately absent: a resolver performs
  7	//! effects OUTSIDE the query engine and submits a new Jurisdiction
  8	//! transaction; pure queries then consume that accepted input (v4 §24, §8.6).
  9	//! This is the Salsa boundary adopted verbatim — pure tracked queries versus
 10	//! external input mutation, extended with Workspace Basis and freshness
 11	//! rather than performing effects inside queries (v4 §118A).
 12	//!
 13	//! **RESERVED — implementation begins Phase -1.3** (v4 Part XXII), where the
 14	//! revision/Basis/invalidation prototype promotes a tiny pure query layer.
 15	//! No memoization, no Salsa dependency, no parallel scheduling before then
 16	//! (Law 14: interpretive reference semantics only).
 17	//!
 18	//! This crate exists now so the constitutional vocabulary has a compiled,
 19	//! greppable home: the trait seams below let the §112 correctness laws
 20	//! (`incremental_compile(x, edits) ≡ full_compile(apply(x, edits))`) compile
 21	//! as generic functions in the conformance suite today, years before the
 22	//! first real implementation plugs in.
