648	/// While the packet is unqualified, a rendered table may carry only what the
649	/// PACKET already declares — family names, predeclared counts, the declared
650	/// fuzz budget — and otherwise must claim nothing. The flip is the only thing
651	/// that may write a result, and it runs only on a qualified packet, so any
652	/// other value in these tables is drift (A09).
653	fn verify_markdown_tables(root: &Utf8Path, packet: &Packet) -> Result<()> {
654	    let path = root.join("docs/execution/phase1-suite-review.md");
655	    let text = fs::read_to_string(&path).with_context(|| format!("read {path}"))?;
656	    // Blind pass 1 at ee646f8c (A09): this returned here for any qualified
657	    // packet, on the reasoning that "the rest are bound by the packet digest
658	    // this markdown carries". They are not. The digest binds the packet;
659	    // editing a cell of this markdown leaves it untouched, so every table
660	    // outside the review blocks went unchecked the moment provenance existed.
661	    // Qualification changes exactly one thing: the flip may write results. So
662	    // the shapes are checked either way, and only the value rule relaxes.
663	    let qualified = packet.provenance.is_some();
664	    let mut declared = BTreeSet::new();
665	    for mutant in &packet.mutants {
666	        declared.insert(mutant.family.clone());
667	    }
668	    for row in &packet.generated {
669	        declared.insert(row.family.clone());
670	        declared.insert(row.accepted.to_string());
671	    }
672	    let mut by_family = BTreeMap::<&str, usize>::new();
673	    for mutant in &packet.mutants {
