247	        let mut entries = fs::read_dir(dir.as_std_path())
248	            .with_context(|| format!("read {dir}"))?
249	            .map(|entry| entry.map(|e| e.path()))
250	            .collect::<std::io::Result<Vec<_>>>()?;
251	        entries.sort();
252	        for entry in entries {
253	            let entry = Utf8PathBuf::from_path_buf(entry)
254	                .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
255	            if entry.is_dir() {
256	                stack.push(entry);
