300	                            break;
301	                        };
302	                        qualifiers.replace_range(start..=start + offset, "");
303	                    }
304	                    qualifiers
305	                        .split_whitespace()
306	                        .all(|word| matches!(word, "pub" | "async" | "const" | "unsafe"))
307	                })
308	                .map(|(_, rest)| rest)?;
309	            let end = rest.find(['(', '<'])?;
310	            Some(rest[..end].to_owned())
311	        })
312	        .collect::<BTreeSet<_>>();
313	    let mut seen = BTreeSet::new();
314	    let mut queue = vec![name.to_owned()];
315	    let mut combined = String::new();
316	    while let Some(current) = queue.pop() {
317	        if !seen.insert(current.clone()) {
318	            continue;
319	        }
320	        for body in item_bodies(text, &current) {
321	            combined.push_str(body);
322	            combined.push('\n');
323	            for callee in &defined {
324	                // Blind pass 1 at `6b36bbb9` (A01): only the CALL form was
325	                // followed, so `let h = helper; h(input)` carried the oracle
326	                // to a body the closure never entered — the same value
327	                // indirection that defeated the alias scan one lane earlier.
328	                // Naming a function at all pulls its body in.
329	                if !seen.contains(callee) && mentions_word(body, callee) {
330	                    queue.push(callee.clone());
331	                }
332	            }
333	        }
334	    }
335	    combined
336	}
