338	/// Whether `text` uses `word` as a whole identifier. `contains` would match a
339	/// one-letter alias inside every other identifier in the file.
340	fn mentions_word(text: &str, word: &str) -> bool {
341	    text.match_indices(word).any(|(at, _)| {
342	        let before = text[..at].chars().next_back();
343	        let after = text[at + word.len()..].chars().next();
344	        let boundary = |ch: Option<char>| !ch.is_some_and(|c| c.is_alphanumeric() || c == '_');
345	        boundary(before) && boundary(after)
346	    })
347	}
