532	/// that rule to catch. Only the ID set was ever checked
533	/// (`verify_markdown_review_blocks`), which a surplus cell does not disturb.
534	const RENDERED_TABLES: [&str; 13] = [
535	    "| Canary ID | Gate/conjunct |",
536	    "| Requirement ID | Kind |",
537	    "| Test ID | Exact test |",
538	    "| Requirement ID | Positive tests |",
