550	/// A cell that asserts nothing: the lane has not run, or the surface is
551	/// quarantined behind Phase 1 authorization (AM-17.2).
552	fn cell_claims_nothing(cell: &str) -> bool {
553	    let cell = cell.trim();
554	    // `NOT_RUN — prohibited` and `QUARANTINED (AM-17.2)` carry a reason after
555	    // the marker, so the marker is a prefix. A reason may not smuggle a
556	    // verdict past the whole-cell check below (review of `a5c27fc`).
557	    let annotated = (cell.starts_with("NOT_RUN ") || cell.starts_with("QUARANTINED"))
558	        && !cell
559	            .split(|ch: char| !ch.is_ascii_alphabetic())
560	            .any(|word| VERDICT_VOCABULARY.contains(&word.to_ascii_lowercase().as_str()));
561	    cell.is_empty()
562	        || cell == "NOT_RUN"
563	        || annotated
564	        || cell.chars().all(|ch| ch == '-' || ch == ':')
565	}
