775	fn verify_markdown_review_blocks(root: &Utf8Path, packet: &Packet) -> Result<()> {
776	    let text = fs::read_to_string(root.join("docs/execution/phase1-suite-review.md"))
777	        .context("read the review markdown")?;
778	    let fields = [
779	        "reviewer identity hash",
780	        "reviewer kind/model family",
781	        "isolated session hash",
782	        "sanitized prompt hash",
783	        "fixed-base hash",
784	        "blindness proof",
785	        "concrete falsification attempts (minimum 12)",
786	        "attempted caught violations",
787	        "findings artifact hash",
788	        "unresolved verified findings",
789	        "result",
790	    ];
791	    let cell = |value: &str| value.replace('|', "\\|").replace('\n', " ");
792	    for (index, review) in packet.reviews.iter().enumerate() {
793	        let marker = format!("### Pass {}", index + 1);
794	        let block_at = text
795	            .find(&marker)
796	            .with_context(|| format!("review markdown has no {marker:?} block"))?;
797	        let block = &text[block_at..];
798	        let block = &block[..block[1..].find("\n### ").map_or(block.len(), |i| i + 1)];
799	        let row_value = |field: &str| -> Result<String> {
800	            let prefix = format!("| {field} | ");
801	            let line = block
802	                .lines()
803	                .find(|line| line.starts_with(&prefix))
804	                .with_context(|| format!("{marker}: no row for {field:?}"))?;
805	            Ok(line[prefix.len()..]
806	                .trim_end()
807	                .trim_end_matches('|')
808	                .trim()
809	                .to_owned())
810	        };
811	        if packet.provenance.is_none() {
812	            for field in fields {
813	                require_eq(&format!("{marker} {field}"), &row_value(field)?, "NOT_RUN")?;
814	            }
815	            continue;
816	        }
817	        let path = review
818	            .evidence
819	            .as_deref()
820	            .with_context(|| format!("{marker}: qualified review row names no record"))?;
821	        let record_path = safe_repo_path(root, path, "review record")?;
822	        let record: ReviewRecord = serde_json::from_slice(&fs::read(&record_path)?)
823	            .with_context(|| format!("parse {record_path}"))?;
824	        let expected = expected_review_rows(&record);
825	        for (field, value) in expected {
826	            require_eq(
827	                &format!("{marker} {field}"),
828	                &row_value(field)?,
829	                &cell(&value),
830	            )?;
831	        }
832	    }
833	    Ok(())
834	}
