   168	/// Extract item beginning at line byte `start`, counting only structural
   169	/// braces. Strings/comments can contain bare `}` and must not terminate the
   170	/// body (HAQP blind pass A02).
   171	fn item_body_from_start(text: &str, start: usize) -> Option<&str> {
   172	    let mut scanner = SourceScanner::default();
   173	    let mut depth = 0i32;
   174	    let mut opened = false;
   175	    let mut end = start;
   176	    for line in text[start..].split_inclusive('\n') {
   177	        let structural = scanner.structural(line);
   178	        let opens = i32::try_from(structural.matches('{').count()).ok()?;
   179	        let closes = i32::try_from(structural.matches('}').count()).ok()?;
   180	        if !opened && opens > 0 {
   181	            opened = true;
   182	        }
   183	        if opened {
   184	            depth += opens - closes;
   185	            if depth < 0 {
   186	                return None;
   187	            }
   188	        }
   189	        end += line.len();
   190	        if opened && depth == 0 {
   191	            return Some(&text[start..end]);
   192	        }
   193	    }
   194	    None
   195	}
