   168	/// Extract item beginning at line byte `start`, counting only structural
   169	/// braces. Strings/comments can contain bare `}` and must not terminate the
   170	/// body (HAQP blind pass A02).
   171	fn item_body_from_start(text: &str, start: usize) -> Option<&str> {
   172	    let mut scanner = SourceScanner::default();
   173	    let mut depth = 0i32;
   174	    let mut opened = false;
   175	    let mut end = start;
   176	    for line in text[start..].split_inclusive('\n') {
   177	        let structural = scanner.structural(line);
   178	        let opens = i32::try_from(structural.matches('{').count()).ok()?;
   179	        let closes = i32::try_from(structural.matches('}').count()).ok()?;
   180	        if !opened && opens > 0 {
   181	            opened = true;
   182	        }
   183	        if opened {
   184	            depth += opens - closes;
   185	            if depth < 0 {
   186	                return None;
   187	            }
   188	        }
   189	        end += line.len();
   190	        if opened && depth == 0 {
   191	            return Some(&text[start..end]);
   192	        }
   193	    }
   194	    None
   195	}
   196	
   197	/// The body of `name` in `text`, using the lexical scanner to locate the
   198	/// definition and to find its matching structural closing brace.
   199	fn item_body<'a>(text: &'a str, name: &str) -> Option<&'a str> {
   200	    let needle = format!("fn {name}(");
   201	    let mut scanner = SourceScanner::default();
   202	    let mut offset = 0;
   203	    for line in text.split_inclusive('\n') {
   204	        if scanner.structural(line).contains(&needle) {
   205	            return item_body_from_start(text, offset);
   206	        }
   207	        offset += line.len();
   208	    }
   209	    None
   210	}
   211	
   212	/// Every definition of `name` in `text`. All of them, not the first: a crate's
   213	/// modules concatenate here, and two modules may name a function alike.
   214	fn item_bodies<'a>(text: &'a str, name: &str) -> Vec<&'a str> {
   215	    // Blind pass 1 at `0a0b4b4b` (A02): a macro is an item the oracle can
   216	    // reach, and its body is where the production call would sit — following
   217	    // functions alone left `production!()` outside the scanned body.
   218	    let needles = [format!("fn {name}("), format!("macro_rules! {name}")];
   219	    let mut scanner = SourceScanner::default();
   220	    let mut starts = BTreeSet::new();
   221	    let mut offset = 0;
   222	    for line in text.split_inclusive('\n') {
   223	        let structural = scanner.structural(line);
   224	        if needles.iter().any(|needle| structural.contains(needle)) {
   225	            starts.insert(offset);
   226	        }
   227	        offset += line.len();
   228	    }
   229	    starts
   230	        .into_iter()
   231	        .filter_map(|start| item_body_from_start(text, start))
   232	        .collect()
   233	}
