   235	/// The crate's own sources, concatenated, for the crate owning `file`. Blind
   236	/// pass 1 at c29bc0ea (A02): the closure followed same-file functions only, so
   237	/// a helper one module away carried the oracle to the production path it
   238	/// judges and named nothing.
   239	fn crate_sources(root: &Utf8Path, file: &str) -> Result<String> {
   240	    let path = root.join(file);
   241	    let Some(src) = path.parent() else {
   242	        return fs::read_to_string(&path).with_context(|| format!("read {path}"));
   243	    };
   244	    let mut stack = vec![src.to_owned()];
   245	    let mut files = Vec::new();
   246	    while let Some(dir) = stack.pop() {
   247	        let mut entries = fs::read_dir(dir.as_std_path())
   248	            .with_context(|| format!("read {dir}"))?
   249	            .map(|entry| entry.map(|e| e.path()))
   250	            .collect::<std::io::Result<Vec<_>>>()?;
   251	        entries.sort();
   252	        for entry in entries {
   253	            let entry = Utf8PathBuf::from_path_buf(entry)
   254	                .map_err(|p| anyhow::anyhow!("non-UTF-8 path {}", p.display()))?;
   255	            if entry.is_dir() {
   256	                stack.push(entry);
   257	            } else if entry.extension() == Some("rs") {
   258	                files.push(entry);
   259	            }
   260	        }
   261	    }
   262	    files.sort();
   263	    let mut combined = String::new();
   264	    for file in files {
   265	        combined.push_str(&fs::read_to_string(&file).with_context(|| format!("read {file}"))?);
   266	        combined.push('\n');
   267	    }
   268	    Ok(combined)
   269	}
