   271	/// Every function in `text` reachable from `name`, concatenated. A helper the
   272	/// oracle calls is part of the oracle for ADR-0020 §5: independence that one
   273	/// hop defeats is not independence.
   274	fn oracle_reachable_body(text: &str, name: &str) -> String {
   275	    let defined = text
   276	        .lines()
   277	        .filter_map(|line| {
   278	            let trimmed = line.trim_start();
   279	            // Review of f4d42d3: `pub(crate) fn helper` named no prefix, so a
   280	            // helper declared that way was missing from the closure and the
   281	            // oracle could reach production through it. Review of 4bc26b6d:
   282	            // the first fix tested `pub(...)` as a whole-prefix alternative,
   283	            // which `pub(crate) async fn` fails on both arms. Review of
   284	            // `39de4daa`: a per-word check still missed `pub(in crate::x) fn`,
   285	            // which splits into two words. The restriction is removed as a
   286	            // span, then the remaining qualifiers are checked word by word.
   287	            // `unsafe` is among them because adding a helper to the closure
   288	            // can only add refusals; dropping one is the direction that lets
   289	            // an oracle reach production unnoticed.
   290	            if let Some(rest) = trimmed.strip_prefix("macro_rules! ") {
   291	                let end = rest.find(['{', '(', '[']).unwrap_or(rest.len());
   292	                return Some(rest[..end].trim().to_owned());
   293	            }
   294	            let rest = trimmed
   295	                .split_once("fn ")
   296	                .filter(|(before, _)| {
   297	                    let mut qualifiers = (*before).to_owned();
   298	                    while let Some(start) = qualifiers.find("pub(") {
   299	                        let Some(offset) = qualifiers[start..].find(')') else {
   300	                            break;
   301	                        };
   302	                        qualifiers.replace_range(start..=start + offset, "");
   303	                    }
   304	                    qualifiers
   305	                        .split_whitespace()
   306	                        .all(|word| matches!(word, "pub" | "async" | "const" | "unsafe"))
   307	                })
   308	                .map(|(_, rest)| rest)?;
   309	            let end = rest.find(['(', '<'])?;
   310	            Some(rest[..end].to_owned())
   311	        })
   312	        .collect::<BTreeSet<_>>();
   313	    let mut seen = BTreeSet::new();
   314	    let mut queue = vec![name.to_owned()];
   315	    let mut combined = String::new();
   316	    while let Some(current) = queue.pop() {
   317	        if !seen.insert(current.clone()) {
   318	            continue;
   319	        }
   320	        for body in item_bodies(text, &current) {
   321	            combined.push_str(body);
   322	            combined.push('\n');
   323	            for callee in &defined {
   324	                // Blind pass 1 at `6b36bbb9` (A01): only the CALL form was
   325	                // followed, so `let h = helper; h(input)` carried the oracle
   326	                // to a body the closure never entered — the same value
   327	                // indirection that defeated the alias scan one lane earlier.
   328	                // Naming a function at all pulls its body in.
   329	                if !seen.contains(callee) && mentions_word(body, callee) {
   330	                    queue.push(callee.clone());
   331	                }
   332	            }
   333	        }
   334	    }
   335	    combined
   336	}
