2193	fn ordered_block_contents(text: &str) -> BTreeMap<String, Vec<String>> {
2194	    let mut anonymous = 0usize;
2195	    let mut blocks = BTreeMap::new();
2196	    for block in text.split("\n\n") {
2197	        let marker = block
2198	            .split_whitespace()
2199	            .find(|token| token.starts_with("{#") && token.ends_with('}'))
2200	            .map_or_else(
2201	                || {
2202	                    let key = format!("anon:{anonymous}");
2203	                    anonymous += 1;
2204	                    key
2205	                },
2206	                str::to_owned,
2207	            );
2208	        let tokens = block
2209	            .split_whitespace()
2210	            .filter(|token| !token.starts_with("{#") || !token.ends_with('}'))
2211	            .map(str::to_owned)
2212	            .collect::<Vec<_>>();
2213	        // Blocks containing only marker tokens carry no ordinary content whose
2214	        // order can falsify this ordering oracle; marker order is checked above.
2215	        if !tokens.is_empty() {
2216	            blocks.insert(marker, tokens);
2217	        }
2218	    }
2219	    blocks
2220	}
