2261	/// Independent invalidation oracle. It compares expected read membership to
2262	/// observed invalidation answers, including a negative witness.
2263	fn independent_oracle_source_invalidation(
2264	    deps: &mut liminal_revision::ComponentDeps,
2265	    expected: &BTreeSet<liminal_id::JurisdictionKey>,
2266	    unrelated: &liminal_id::JurisdictionKey,
2267	    extra: &liminal_id::JurisdictionKey,
2268	) -> Result<Vec<u8>> {
2269	    for key in expected {
2270	        anyhow::ensure!(
2271	            deps.invalidated_by(key),
2272	            "a recorded read did not invalidate: {key:?}"
2273	        );
2274	    }
2275	    anyhow::ensure!(
2276	        !deps.invalidated_by(unrelated),
2277	        "an unread key invalidated the computation: {unrelated:?}"
2278	    );
2279	    // Add a new dependency only between observations. This makes the second
2280	    // check a real monotonicity assertion instead of repeating the first one.
2281	    anyhow::ensure!(
2282	        !deps.invalidated_by(extra),
2283	        "extra dependency was already present before monotonicity probe: {extra:?}"
2284	    );
2285	    deps.record(extra.clone());
2286	    // Blind pass 1 at aa00d41 (A03): the relation only re-checked the keys that
2287	    // already invalidated, so a `record` that did nothing passed. Monotonicity
2288	    // is that the new read is now observed AND no old one was lost.
2289	    anyhow::ensure!(
2290	        deps.invalidated_by(extra),
2291	        "recording a read did not make it invalidate: {extra:?}"
2292	    );
2293	    for key in expected {
2294	        anyhow::ensure!(
2295	            deps.invalidated_by(key),
2296	            "recording another read un-invalidated {key:?}"
2297	        );
2298	    }
2299	    anyhow::ensure!(
2300	        !deps.invalidated_by(unrelated),
2301	        "recording a read invalidated an unread key: {unrelated:?}"
2302	    );
2303	    let mut witness = Vec::new();
2304	    for key in expected.iter().chain([unrelated, extra]) {
2305	        witness.push(u8::from(deps.invalidated_by(key)));
2306	    }
2307	    Ok(witness)
2308	}
