1723	/// Independent source/CST oracle. It compares raw observed bytes, not parser
1724	/// equality or a formatter-owned snapshot.
1725	/// The coarse scan judged against the source directly, never against the fine
1726	/// parse: presence, ranges, classification and the hash relation. Returns the
1727	/// classifications and hashes so the case witness binds them.
1728	#[allow(clippy::too_many_lines)]
1729	fn verify_coarse_scan(
1730	    source: &str,
1731	    coarse: &liminal_cst::CstDocument,
1732	) -> Result<(Vec<&'static str>, Vec<String>)> {
1733	    // The coarse scan is judged against the source directly, never against
1734	    // the fine parse: a document with a non-blank line has at least one block,
1735	    // every block's range lies inside the source and holds no blank line, and
1736	    // the blocks do not overlap (A01).
