1738	        coarse.source == source,
1739	        "coarse_parse changed the source it was given"
1740	    );
1741	    let has_content = source.lines().any(|line| !line.trim().is_empty());
1742	    anyhow::ensure!(
1743	        has_content != coarse.blocks.is_empty(),
1744	        "coarse_parse found {} blocks for a document that {} content",
1745	        coarse.blocks.len(),
1746	        if has_content { "has" } else { "has no" }
1747	    );
