1752	    let mut line_start = 0usize;
1753	    for line in source.split_inclusive('\n') {
1754	        let line_end = line_start + line.len();
1755	        if line.trim().is_empty() {
1756	            if let Some(start) = expected_start.take() {
1757	                expected_ranges.push((start, line_start));
1758	            }
1759	        } else if expected_start.is_none() {
1760	            expected_start = Some(line_start);
1761	        }
1762	        line_start = line_end;
1763	    }
1764	    if let Some(start) = expected_start {
1765	        expected_ranges.push((start, source.len()));
1766	    }
1767	    anyhow::ensure!(
1768	        coarse.blocks.len() == expected_ranges.len(),
1769	        "coarse scan reported {} blocks, expected {} blank-line blocks",
1770	        coarse.blocks.len(),
1771	        expected_ranges.len()
1772	    );
1773	    for (index, (block, (expected_start, expected_end))) in
1774	        coarse.blocks.iter().zip(expected_ranges).enumerate()
1775	    {
1776	        let actual_start = usize::try_from(block.range.start).unwrap_or(usize::MAX);
1777	        let actual_end = usize::try_from(block.range.end).unwrap_or(usize::MAX);
1778	        anyhow::ensure!(
1779	            (actual_start, actual_end) == (expected_start, expected_end),
1780	            "coarse block {index} has range {actual_start}..{actual_end}, expected {expected_start}..{expected_end}"
1781	        );
1782	    }
1783	    let mut previous_end = 0usize;
1784	    let mut kinds = Vec::new();
1785	    let mut hashes = Vec::new();
1786	    let mut by_text: BTreeMap<&str, String> = BTreeMap::new();
1787	    let mut by_hash: BTreeMap<String, &str> = BTreeMap::new();
1788	    for block in &coarse.blocks {
1789	        let start = usize::try_from(block.range.start).unwrap_or(usize::MAX);
1790	        let end = usize::try_from(block.range.end).unwrap_or(usize::MAX);
1791	        anyhow::ensure!(
