1878	/// A document's words in order. An escape stands for the character it
1879	/// denotes, so `\n` inside an emitted literal is a separator and not the
1880	/// letter `n` glued to the next word — without that, escaping a newline
1881	/// looks like reordering.
1882	///
1883	/// Review of `ec045588`: an escape the emitter does not produce — `\u` with
1884	/// too few hex digits, say — is normalised imperfectly, and that is safe
1885	/// because this runs over BOTH sides. Mangling can only add words to the
1886	/// output, never remove one from the source, and added words are what a
1887	/// subsequence tolerates. Every character the emitter actually escapes is
1888	/// non-alphanumeric, so it already separates words in the source.
1889	fn sequence(text: &str) -> Vec<String> {
1890	    let mut plain = String::with_capacity(text.len());
1891	    let mut chars = text.chars().peekable();
1892	    while let Some(ch) = chars.next() {
1893	        if ch != '\\' {
1894	            plain.push(ch);
1895	            continue;
1896	        }
1897	        // `\uXXXX` and `\xNN` denote one character each; anything else
1898	        // after a backslash denotes the character that follows it.
1899	        let digits = match chars.peek() {
1900	            Some('u') => 4,
1901	            Some('x') => 2,
1902	            _ => 0,
1903	        };
1904	        chars.next();
1905	        for _ in 0..digits {
1906	            if chars.peek().is_some_and(char::is_ascii_hexdigit) {
1907	                chars.next();
1908	            }
1909	        }
1910	        plain.push(' ');
1911	    }
1912	    plain
1913	        .split(|ch: char| !ch.is_alphanumeric())
1914	        .filter(|run| !run.is_empty())
1915	        .map(str::to_owned)
1916	        .collect()
1917	}
