2056	/// Independent merge oracle. It checks raw content and outcome classes, plus
2057	/// result equality for the category that declares independent edits.
2058	fn independent_oracle_source_transform(
2059	    category: &str,
2060	    base: &str,
2061	    ours: &str,
2062	    theirs: &str,
2063	    identity: &liminal_source::merge::MergeOutcome,
2064	    forward: &liminal_source::merge::MergeOutcome,
2065	    swapped: &liminal_source::merge::MergeOutcome,
2066	) -> Result<Vec<u8>> {
2067	    let liminal_source::merge::MergeOutcome::Disjoint { merged } = identity else {
2068	        anyhow::bail!("identity merge reported non-disjoint outcome: {identity:?}");
2069	    };
2070	    let merged_tokens = merged.split_whitespace().collect::<Vec<_>>();
2071	    let ours_tokens = ours.split_whitespace().collect::<Vec<_>>();
2072	    let mut merged_multiset = merged_tokens.clone();
2073	    let mut ours_multiset = ours_tokens.clone();
2074	    merged_multiset.sort_unstable();
2075	    ours_multiset.sort_unstable();
2076	    anyhow::ensure!(
2077	        ours_multiset == merged_multiset,
2078	        "identity merge dropped content: {ours:?} -> {merged:?}"
2079	    );
2080	    // Token multisets alone permit an implementation to drop or duplicate
2081	    // durable markers. The merge contract keeps base slot order as its primary
2082	    // layout; a pure move is therefore intentionally not an order-preserving
2083	    // relation, but its marker set must still survive exactly.
2084	    let marker_order = |text: &str| {
2085	        text.split_whitespace()
2086	            .filter(|token| token.starts_with("{#") && token.ends_with('}'))
2087	            .map(str::to_owned)
2088	            .collect::<Vec<_>>()
2089	    };
2090	    let base_markers = marker_order(base);
2091	    let ours_markers = marker_order(ours);
2092	    if ours_markers != base_markers {
2093	        let mut expected = ours_markers.clone();
2094	        let mut actual = marker_order(merged);
2095	        expected.sort_unstable();
2096	        actual.sort_unstable();
2097	        anyhow::ensure!(
2098	            actual == expected,
2099	            "identity merge changed durable marker set under layout normalization"
2100	        );
2101	        // Blind pass 1 at 612cbcc (A02): the marker SET surviving a move said
2102	        // nothing about which content each marker kept; swapping the contents
2103	        // of two moved markers passed. A move keeps every marker's content.
2104	        let markered = |text: &str| {
2105	            ordered_block_contents(text)
2106	                .into_iter()
2107	                .filter(|(marker, _)| marker.starts_with("{#"))
2108	                .collect::<BTreeMap<_, _>>()
2109	        };
2110	        anyhow::ensure!(
2111	            markered(merged) == markered(ours),
2112	            "identity merge re-associated content across moved markers: {ours:?} -> {merged:?}"
2113	        );
2114	    }
2115	    if ours_markers == base_markers {
2116	        anyhow::ensure!(
2117	            marker_order(merged) == ours_markers,
2118	            "identity merge reordered durable markers"
2119	        );
2120	        anyhow::ensure!(
2121	            ordered_block_contents(merged) == ordered_block_contents(ours),
2122	            "identity merge reordered ordinary content: {ours:?} -> {merged:?}"
2123	        );
2124	    }
2125	    // A12: outcome-class symmetry alone lets a merge drop one side's edit while
2126	    // both forward and swapped results remain `Disjoint`. For every token a
2127	    // side added beyond the base, require the corresponding disjoint result to
2128	    // retain that multiplicity. This checks content without reusing merge code.
2129	    let require_additions = |side: &str, merged: &str, label: &str| -> Result<()> {
2130	        let counts = |text: &str| {
2131	            text.split_whitespace()
2132	                .fold(BTreeMap::new(), |mut counts, token| {
2133	                    *counts.entry(token.to_owned()).or_insert(0usize) += 1;
2134	                    counts
2135	                })
2136	        };
2137	        let base_counts = counts(base);
2138	        let side_counts = counts(side);
2139	        let merged_counts = counts(merged);
2140	        for (token, side_count) in side_counts {
2141	            let base_count = base_counts.get(&token).copied().unwrap_or(0);
2142	            if side_count > base_count {
2143	                anyhow::ensure!(
2144	                    merged_counts.get(&token).copied().unwrap_or(0) >= side_count,
2145	                    "disjoint {label} merge dropped added token {token:?}: {side:?} -> {merged:?}"
2146	                );
2147	            }
2148	        }
2149	        Ok(())
2150	    };
2151	    if let liminal_source::merge::MergeOutcome::Disjoint { merged } = &forward {
2152	        require_additions(ours, merged, "forward/ours")?;
2153	        require_additions(theirs, merged, "forward/theirs")?;
2154	    }
2155	    if let liminal_source::merge::MergeOutcome::Disjoint { merged } = &swapped {
2156	        require_additions(ours, merged, "swapped/ours")?;
2157	        require_additions(theirs, merged, "swapped/theirs")?;
2158	    }
2159	    let disjoint = |outcome: &liminal_source::merge::MergeOutcome| {
2160	        matches!(
2161	            outcome,
2162	            liminal_source::merge::MergeOutcome::Disjoint { .. }
2163	        )
2164	    };
2165	    anyhow::ensure!(
2166	        disjoint(forward) == disjoint(swapped),
2167	        "merge disjointness is not symmetric under swapping sides"
2168	    );
2169	    if category == "commute" {
2170	        require_commuting_source_outcomes(forward, swapped)?;
2171	    }
2172	    Ok(format!("{identity:?}|{forward:?}|{swapped:?}").into_bytes())
2173	}
