2261	/// Independent invalidation oracle. It compares expected read membership to
2262	/// observed invalidation answers, including a negative witness.
2263	fn independent_oracle_source_invalidation(
2264	    deps: &mut liminal_revision::ComponentDeps,
2265	    expected: &BTreeSet<liminal_id::JurisdictionKey>,
2266	    unrelated: &liminal_id::JurisdictionKey,
2267	    extra: &liminal_id::JurisdictionKey,
2268	) -> Result<Vec<u8>> {
2269	    for key in expected {
2270	        anyhow::ensure!(
2271	            deps.invalidated_by(key),
2272	            "a recorded read did not invalidate: {key:?}"
2273	        );
2274	    }
2275	    anyhow::ensure!(
2276	        !deps.invalidated_by(unrelated),
2277	        "an unread key invalidated the computation: {unrelated:?}"
2278	    );
2279	    // Add a new dependency only between observations. This makes the second
2280	    // check a real monotonicity assertion instead of repeating the first one.
2281	    anyhow::ensure!(
2282	        !deps.invalidated_by(extra),
