2291	        "recording a read did not make it invalidate: {extra:?}"
2292	    );
2293	    for key in expected {
2294	        anyhow::ensure!(
2295	            deps.invalidated_by(key),
2296	            "recording another read un-invalidated {key:?}"
2297	        );
2298	    }
2299	    anyhow::ensure!(
2300	        !deps.invalidated_by(unrelated),
2301	        "recording a read invalidated an unread key: {unrelated:?}"
2302	    );
2303	    let mut witness = Vec::new();
2304	    for key in expected.iter().chain([unrelated, extra]) {
2305	        witness.push(u8::from(deps.invalidated_by(key)));
