1919	fn independent_oracle_source_cst(
1920	    source: &str,
1921	    emitted: &str,
1922	    once: &str,
1923	    twice: &str,
1924	    content: &str,
1925	    coarse: &liminal_cst::CstDocument,
1926	) -> Result<Vec<u8>> {
1927	    anyhow::ensure!(emitted == source, "CST emit is not lossless for {source:?}");
1928	    anyhow::ensure!(once == twice, "formatting is not idempotent");
1929	    // Blind pass 1 at 5fb1b57 (A01): those two say nothing about whether
1930	    // formatting KEPT the document. A formatter returning a constant is
1931	    // idempotent, and the lossless check never touches the formatter at all.
1932	    // The generated word is content, not layout: formatting may move it, never
1933	    // lose it. A durable-marker set would be the natural check and is nearly
1934	    // vacuous for this corpus, where only the malformed categories carry `{#`.
1935	    // Alphanumeric runs, not the raw token: a generated word can begin with
1936	    // markdown syntax (`- v`), and lowering `- ` into list structure is the
1937	    // formatter doing its job, not losing content.
1938	    // Blind pass 1 at 91b54842 (A01): the runs were filtered to three
1939	    // characters and up. `Rng::word` draws one to twelve characters from an
1940	    // alphabet holding `-`, `_` and a space, so `a`, `x y` and `a-b` are all
1941	    // reachable tokens with no run that long — for those the survival check
1942	    // had nothing to check and a formatter could drop the content outright.
1943	    // Every non-empty run counts now. The dialect numbers nothing (an ordered
1944	    // block is the keyword `ordered`, never `1.`), so no digit legitimately
1945	    // disappears, and a one-character run is weak rather than false: it fires
1946	    // only when that character is absent from the whole output.
1947	    let words = |text: &str| {
1948	        text.split(|ch: char| !ch.is_alphanumeric())
1949	            .filter(|run| !run.is_empty())
1950	            .map(str::to_owned)
1951	            .collect::<BTreeSet<_>>()
1952	    };
1953	    let lost = words(content)
1954	        .into_iter()
1955	        .filter(|word| source.contains(word.as_str()) && !once.contains(word.as_str()))
1956	        .collect::<Vec<_>>();
1957	    // Blind pass 1 at `6b36bbb9` (A09): survival was judged on alphanumeric
1958	    // runs, so content that is punctuation raised nothing — a token of `_`
1959	    // has no run at all and could be dropped in silence. A character is
1960	    // markup only if the dialect lowers it: `-`, `*`, `#`, `>`, `|`, `+` and
1961	    // a backtick begin lists, headings, quotes, tables and fences, and
1962	    // lowering those is the formatter doing its job. Everything else that is
1963	    // not whitespace is content and must come back.
1964	    let lost_marks = content
1965	        .chars()
1966	        .filter(|ch| {
1967	            !ch.is_whitespace()
1968	                && !ch.is_alphanumeric()
1969	                && !STRUCTURAL_MARKUP.contains(ch)
1970	                && source.contains(*ch)
1971	                && !once.contains(*ch)
1972	        })
1973	        .collect::<BTreeSet<_>>();
1974	    anyhow::ensure!(
1975	        lost_marks.is_empty(),
1976	        "formatting dropped the document's punctuation content {lost_marks:?}: {source:?} -> \
1977	         {once:?}"
1978	    );
1979	    anyhow::ensure!(
1980	        lost.is_empty(),
1981	        "formatting dropped the document's content {lost:?}: {source:?} -> {once:?}"
1982	    );
1983	    // Blind pass 1 at `0a0b4b4b` (A01): membership was checked and ORDER was
1984	    // not, so a formatter that scrambled a document's words kept every word,
1985	    // every mark, non-emptiness and idempotence, and lost the meaning. A
1986	    // formatter may move a word between lines; it may never move one past
1987	    // another, so the sequence of alphanumeric runs is invariant.
1988	    // Formatting may ADD words — the explicit dialect wraps content in `node`,
1989	    // `paragraph`, `literal` — so the source's words must appear in the output
1990	    // in their own order, not as the whole of it.
1991	    let emitted_words = sequence(once);
1992	    let source_words = sequence(source);
1993	    let mut next = emitted_words.iter();
1994	    if !source_words
1995	        .iter()
1996	        .all(|word| next.any(|candidate| candidate == word))
1997	    {
1998	        // Review of `ec045588`: a subsequence fails for two different reasons
1999	        // and they are not the same defect. If some word appears fewer times
2000	        // in the output than in the source, the formatter dropped a copy —
2001	        // which the loss check above cannot see, because it asks whether the
2002	        // word survives at all and not how often. Otherwise every word is
2003	        // present the right number of times and the order changed.
2004	        let count = |words: &[String], word: &String| words.iter().filter(|w| *w == word).count();
2005	        let dropped = source_words
2006	            .iter()
2007	            .find(|word| count(&source_words, word) > count(&emitted_words, word));
2008	        anyhow::ensure!(
2009	            dropped.is_none(),
2010	            "formatting dropped a copy of {:?}: {source:?} -> {once:?}",
2011	            dropped.expect("checked")
2012	        );
2013	        anyhow::bail!("formatting reordered the document's words: {source:?} -> {once:?}");
2014	    }
2015	    anyhow::ensure!(
2016	        source.trim().is_empty() || !once.trim().is_empty(),
2017	        "formatting emptied a non-empty document"
2018	    );
2019	    let (kinds, hashes) = verify_coarse_scan(source, coarse)?;
2020	    // Blind pass 1 at `cbed339f` (A01): lowering a marker is the formatter's
2021	    // job, and dropping one is not, and nothing told the two apart. `- alpha`
2022	    // formatted to a bare `alpha` kept every word and lost the list. Every
2023	    // block the scan classifies as structure must come back as the explicit
2024	    // node the dialect lowers it to, or verbatim, as a region the formatter
2025	    // preserved rather than canonicalized (D20.6).
2026	    for block in &coarse.blocks {
2027	        let node = match block.coarse_kind {
2028	            liminal_cst::CoarseKind::List => "node unordered-list",
2029	            liminal_cst::CoarseKind::Heading => "node heading",
2030	            liminal_cst::CoarseKind::Fence => "node code-block",
2031	            _ => continue,
2032	        };
2033	        let range = usize::try_from(block.range.start)?..usize::try_from(block.range.end)?;
2034	        let first = source
2035	            .get(range)
2036	            .context("the coarse scan's block lies inside its source")?
2037	            .lines()
2038	            .next()
2039	            .unwrap_or_default()
2040	            .trim();
2041	        anyhow::ensure!(
2042	            once.contains(node) || once.contains(first),
2043	            "formatting dropped the structure of {:?} block {first:?}: neither {node:?} nor \
2044	             the block itself survives: {source:?} -> {once:?}",
2045	            block.coarse_kind
2046	        );
2047	    }
2048	    let mut witness = emitted.as_bytes().to_vec();
2049	    witness.extend_from_slice(once.as_bytes());
2050	    witness.extend_from_slice(format!("coarse:{}", coarse.blocks.len()).as_bytes());
2051	    witness.extend_from_slice(kinds.join(",").as_bytes());
2052	    witness.extend_from_slice(hashes.join(",").as_bytes());
2053	    Ok(witness)
2054	}
