2175	fn require_commuting_source_outcomes(
2176	    forward: &liminal_source::merge::MergeOutcome,
2177	    swapped: &liminal_source::merge::MergeOutcome,
2178	) -> Result<()> {
2179	    let (
2180	        liminal_source::merge::MergeOutcome::Disjoint { merged: forward },
2181	        liminal_source::merge::MergeOutcome::Disjoint { merged: swapped },
2182	    ) = (forward, swapped)
2183	    else {
2184	        anyhow::bail!("independent source edits were not disjoint in both merge orders");
2185	    };
2186	    anyhow::ensure!(
2187	        forward == swapped,
2188	        "independent source edits do not commute: forward={forward:?}, swapped={swapped:?}"
2189	    );
