2222	/// Independent repair oracle. It checks the declared edge set against the
2223	/// returned order and records that permutation of input edges is stable.
2224	fn independent_oracle_source_repair(
2225	    order: &[liminal_id::RepairStepId],
2226	    ids: &[liminal_id::RepairStepId],
2227	    edges: &[(usize, usize)],
2228	    permuted_order: &[liminal_id::RepairStepId],
2229	) -> Result<Vec<u8>> {
