2236	    // in for a missing one. The order is exactly the declared steps, once each.
2237	    let mut declared = ids.to_vec();
2238	    let mut returned = order.to_vec();
2239	    declared.sort_unstable();
2240	    returned.sort_unstable();
2241	    anyhow::ensure!(
2242	        declared == returned && declared.windows(2).all(|pair| pair[0] != pair[1]),
2243	        "ordering dropped, duplicated or invented steps"
2244	    );
2245	    for (before, after) in edges {
2246	        anyhow::ensure!(
2247	            position[&ids[*before]] < position[&ids[*after]],
2248	            "ordering violated a declared dependency"
2249	        );
2250	    }
2251	    anyhow::ensure!(
2252	        permuted_order == order,
2253	        "topological order changed under permutation of dependency edges"
2254	    );
2255	    Ok(order
2256	        .iter()
2257	        .flat_map(|id| id.as_uuid().into_bytes())
2258	        .collect())
2259	}
