2310	fn generated_category_class(category: &str) -> &'static str {
2311	    let category = category.to_ascii_lowercase();
2312	    if category.contains("hostile") {
2313	        "hostile"
2314	    } else if category.contains("truncated") || category.contains("unterminated") {
2315	        "truncated"
2316	    } else if category.contains("invalid")
2317	        || category.contains("malformed")
2318	        || category.contains("unknown")
2319	        || category.contains("missing")
2320	        || category.contains("duplicate")
2321	        || category.contains("cycle")
2322	        || category.contains("conflict")
2323	    {
2324	        "malformed"
