1772	    );
1773	    for (index, (block, (expected_start, expected_end))) in
1774	        coarse.blocks.iter().zip(expected_ranges).enumerate()
1775	    {
1776	        let actual_start = usize::try_from(block.range.start).unwrap_or(usize::MAX);
