1831	            liminal_cst::CoarseKind::Heading => "heading",
1832	            liminal_cst::CoarseKind::List => "list",
1833	            liminal_cst::CoarseKind::Directive => "directive",
1834	            liminal_cst::CoarseKind::ResourceReference => "resource-reference",
