1856	                seen == digest,
1857	                "coarse blocks with identical text hash differently: {text:?}"
1858	            );
1859	        }
1860	        if let Some(seen) = by_hash.insert(digest.clone(), text) {
1861	            anyhow::ensure!(
1862	                seen == text,
1863	                "coarse blocks with different text share hash {digest}: {seen:?} and {text:?}"
1864	            );
1865	        }
