14434	/// Family 0 — source/CST/formatting. Metamorphic relations: **lossless
14435	/// emit** (the CST must reproduce its input byte-for-byte) and **format
14436	/// idempotence**, both compared over bytes rather than parsed values.
14437	fn case_source_cst(rng: &mut Rng) -> Result<Case> {
14438	    // Blind pass 1 at aa00d41 (A01): a formatter error became a Negative case
14439	    // whatever the category, so a formatter that lost support for nested or
14440	    // deep documents reclassified them as negatives and the run still reached
14441	    // its accepted target from the categories that still worked. Only the
14442	    // categories that DECLARE malformed input may be refused.
14443	    const REFUSABLE: [&str; 5] = [
14444	        "truncated",
14445	        "unterminated",
14446	        "control-byte",
14447	        "invalid-utf8",
14448	        "hostile",
14449	    ];
14450	    let category = rng.category("source/CST/formatting");
14451	    let token = rng.word();
14452	    let bytes = match category {
14453	        "empty" => Vec::new(),
14454	        "single-token" => token.as_bytes().to_vec(),
14455	        "whitespace" => b" \t\n".to_vec(),
14456	        "unicode" => format!("{token} βeta").into_bytes(),
14457	        "long-line" => format!("{}-{token}", token.repeat(64)).into_bytes(),
14458	        "truncated" => format!("{token} {{#").into_bytes(),
14459	        "unterminated" => format!("{token} {{#{token}").into_bytes(),
14460	        "nested" => format!("{token} {{#outer {{#{token}}}}}").into_bytes(),
14461	        "deep" => format!("{} {token}", "{#".repeat(24)).into_bytes(),
14462	        // Blind pass 1 at `2bba9071` (A01): `boundary-offset` renders two
14463	        // blocks with IDENTICAL text, which a constant hash satisfies — it
14464	        // passes the equal-text arm and never meets the other. This renders
14465	        // two blocks of DIFFERENT width, so a hash that ignores its bytes
14466	        // collides across them and the relation has both arms to check. A
14467	        // durable marker cannot be used for this: the formatter lifts `{#id}`
14468	        // into an attribute, which moves a word and reads as reordering.
14469	        "wide" => {
14470	            let row = |count: usize| {
14471	                (0..count)
14472	                    .map(|_| token.clone())
14473	                    .collect::<Vec<_>>()
14474	                    .join(" ")
14475	            };
14476	            format!("{}\n\n{}", row(32), row(16)).into_bytes()
14477	        }
14478	        "control-byte" => format!("{token}\x01{token}").into_bytes(),
14479	        "invalid-utf8" => vec![0xff, 0xfe],
14480	        "comment" => format!("{token} <!-- {token} -->").into_bytes(),
14481	        "escape" => format!(r"{token} \ {token}").into_bytes(),
14482	        // Blind pass 1 at `ec045588` (A01): every generated source held at
14483	        // most ONE coarse block, so the per-document hash relation F-60 added
14484	        // — equal text hashes alike, different text does not — had nothing to
14485	        // relate and a constant hash passed 100,000 cases. A blank line makes
14486	        // two blocks, and repeating the token makes them equal, which is the
14487	        // arm a constant hash satisfies and a text-blind one does not.
14488	        "boundary-offset" => format!("{token}\n\n{token}").into_bytes(),
14489	        "hostile" => format!("{token}\0\x7f").into_bytes(),
14490	        other => unreachable!("unknown source category {other}"),
14491	    };
14492	    let Ok(source) = String::from_utf8(bytes.clone()) else {
14493	        let basis = liminal_source::SourceBasis {
14494	            source: liminal_id::SourceId::from_name("haqp-generated"),
14495	            content_hash: liminal_id::ContentHash::of(&bytes),
14496	        };
14497	        anyhow::ensure!(
14498	            liminal_source::Utf8HolderView::from_bytes(basis, &bytes).is_err(),
14499	            "invalid-utf8 source unexpectedly entered Utf8HolderView"
14500	        );
14501	        return Ok(Case::Negative {
14502	            category,
14503	            witness: bytes,
14504	        });
14505	    };
14506	    // Out of domain: the compact surface has no all-whitespace document.
14507	    if source.trim().is_empty() {
14508	        return Ok(Case::Negative {
14509	            category,
14510	            witness: format!("whitespace-source:{source:?}").into_bytes(),
14511	        });
14512	    }
14513	    let basis = liminal_source::SourceBasis {
14514	        source: liminal_id::SourceId::from_name("haqp-generated"),
14515	        content_hash: liminal_id::ContentHash::of(source.as_bytes()),
14516	    };
14517	    let Ok(view) = liminal_source::Utf8HolderView::from_bytes(basis, source.as_bytes()) else {
14518	        return Ok(Case::Negative {
14519	            category,
14520	            witness: source.into_bytes(),
14521	        });
14522	    };
14523	    let cst = liminal_cst::parse(&view);
14524	    let emitted = cst.emit_lossless();
14525	    // Blind pass 1 at 9eca4f0 (A01): the campaign exercised `parse` only, so
14526	    // `coarse_parse` — the other public entry point, the one that must never
14527	    // reject — could return empty block metadata for every input and no
14528	    // generated case would notice.
14529	    let coarse = liminal_cst::coarse_parse(&source);
14530	    let fmt = liminal_format::MarkdownFormatter::default();
14531	    let Ok(once) = fmt.format(&source) else {
14532	        anyhow::ensure!(
14533	            REFUSABLE.contains(&category),
14534	            "the formatter refused valid-domain category {category}: a refusal there is lost \
14535	             support, not a negative case (source {source:?})"
14536	        );
14537	        return Ok(Case::Negative {
14538	            category,
14539	            witness: source.into_bytes(),
14540	        });
14541	    };
14542	    let Ok(twice) = fmt.format(&once) else {
14543	        anyhow::ensure!(
14544	            REFUSABLE.contains(&category),
14545	            "the formatter refused its own output for valid-domain category {category}: \
14546	             formatting is not total there (source {source:?})"
14547	        );
14548	        return Ok(Case::Negative {
14549	            category,
14550	            witness: once.into_bytes(),
14551	        });
14552	    };
14553	    let witness = independent_oracle_source_cst(&source, &emitted, &once, &twice, &token, &coarse)?;
14554	    Ok(Case::Accepted { category, witness })
14555	}
