15479	fn generate_evidence(cases: u64) -> Result<(Vec<GeneratedEvidence>, Vec<u64>)> {
15480	    validate_case_count(cases)?;
15481	    let families: [Family; 5] = [
15482	        ("source/CST/formatting", case_source_cst),
15483	        ("graph/interchange codecs", case_interchange),
15484	        ("transforms/projections", case_transform),
15485	        ("repair/ILRP/recovery", case_repair),
15486	        ("Basis/revision/query invalidation", case_invalidation),
15487	    ];
15488	
15489	    let mut evidence = Vec::new();
15490	    let mut timings = Vec::new();
15491	    for (index, (family, run)) in families.into_iter().enumerate() {
15492	        let seed = 0x9E37_79B9_7F4A_7C15_u64 ^ (index as u64).wrapping_mul(0x0100_0000_01B3);
15493	        let mut rng = Rng(seed);
15494	        let started = Instant::now();
15495	        let mut digest = blake3::Hasher::new();
15496	        digest.update(&seed.to_le_bytes());
15497	        // ADR-0020 §4 requires >=100,000 ACCEPTED cases, so run until the
15498	        // acceptance target is met rather than stopping at N attempts. The
15499	        // attempt cap keeps a badly-targeted generator from running forever
15500	        // instead of silently reporting a short campaign.
15501	        let (mut accepted, mut discards, mut negatives, mut attempts) = (0u64, 0u64, 0u64, 0u64);
15502	        let mut category_counts = BTreeMap::<String, u64>::new();
15503	        // Negative categories are exercised inputs, not discards; families
15504	        // with broad malformed coverage need a larger attempt budget to reach
15505	        // their accepted floor without silently dropping categories.
15506	        let attempt_cap = cases.saturating_mul(4);
15507	        while accepted < cases {
15508	            anyhow::ensure!(
15509	                attempts < attempt_cap,
15510	                "{family}: {attempts} attempts yielded only {accepted}/{cases} accepted \
15511	                 — the generator is not targeting its declared domain"
15512	            );
15513	            attempts += 1;
15514	            match run(&mut rng).with_context(|| format!("{family} attempt {attempts}"))? {
15515	                Case::Accepted { category, witness } => {
15516	                    // A family that witnesses nothing would restore exactly the
15517	                    // #16 defect: a digest independent of the code under test.
15518	                    anyhow::ensure!(
