15520	                        "{family}: accepted attempt {attempts} with an empty witness, so \
15521	                         the evidence hash would not depend on what the code produced"
15522	                    );
15523	                    accepted += 1;
15524	                    *category_counts.entry(category.to_owned()).or_default() += 1;
15525	                    digest.update(b"A");
15526	                    digest.update(category.as_bytes());
15527	                    digest.update(&witness);
15528	                }
15529	                Case::Discarded { category, witness } => {
15530	                    anyhow::ensure!(
15531	                        !witness.is_empty(),
15532	                        "{family}: discarded attempt {attempts} with an empty witness, so \
15533	                         the evidence records that something was discarded and not what"
15534	                    );
15535	                    discards += 1;
15536	                    *category_counts.entry(category.to_owned()).or_default() += 1;
15537	                    digest.update(b"D");
15538	                    digest.update(category.as_bytes());
15539	                    digest.update(&witness);
15540	                }
15541	                Case::Negative { category, witness } => {
15542	                    anyhow::ensure!(
15543	                        !witness.is_empty(),
15544	                        "{family}: negative attempt {attempts} has an empty witness"
15545	                    );
15546	                    negatives += 1;
15547	                    *category_counts.entry(category.to_owned()).or_default() += 1;
15548	                    digest.update(b"N");
15549	                    digest.update(category.as_bytes());
15550	                    digest.update(&witness);
15551	                }
15552	            }
15553	            // The RNG state binds the INPUT; the witness above binds the OUTPUT.
15554	            digest.update(&rng.0.to_le_bytes());
15555	        }
15556	        anyhow::ensure!(
15557	            accepted + discards + negatives == attempts,
15558	            "{family}: accounting lost cases"
15559	        );
15560	        let evidence_hash = digest.finalize().to_hex().to_string();
15561	        let relation_rows = generated_relations(family)
15562	            .iter()
15563	            .map(|relation| GeneratedRelationEvidence {
15564	                relation: (*relation).to_owned(),
15565	                oracle_id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
15566	                result: "pass".to_owned(),
15567	                artifact_blake3: blake3::hash(
15568	                    format!("{family}\0{relation}\0{evidence_hash}").as_bytes(),
15569	                )
