 14557	/// Family 1 — graph/interchange codecs.
 14558	///
 14559	/// Metamorphic relation: **byte-canonical stability**. Re-serializing a value
 14560	/// decoded from canonical bytes must reproduce those bytes exactly. The
 14561	/// comparison is over BYTES, never the type's own `PartialEq`, so a broken
 14562	/// `Eq` cannot make this pass (ADR-0020 §5).
 14563	/// A valid transaction carrying exactly ONE defect, the one `category` names,
 14564	/// in its first created node (A03). The untouched base must decode, and the
 14565	/// mutated bytes must be refused with the error that defect produces -- so a
 14566	/// refusal is attributable to the category rather than to the input merely not
 14567	/// being a transaction.
 14568	fn transaction_with_one_defect(category: &str, rng: &mut Rng) -> Result<Vec<u8>> {
 14569	    let text = format!("{category}:{}", rng.word());
 14570	    let (txn, _) = interchange_transaction("single-edge", rng, &text, false);
 14571	    let base = serde_json::to_value(&txn)?;
 14572	    anyhow::ensure!(
 14573	        serde_json::from_value::<liminal_graph::Transaction>(base.clone()).is_ok(),
 14574	        "graph negative {category}: the base transaction must decode before a defect is added"
 14575	    );
 14576	    let mut value = base;
 14577	    let op = value["ops"]
 14578	        .as_array_mut()
 14579	        .and_then(|ops| ops.iter_mut().find(|op| op.get("create-node").is_some()))
 14580	        .context("graph negative base has no create-node operation")?;
 14581	    let create = op["create-node"]
 14582	        .as_object_mut()
 14583	        .context("create-node is not an object")?;
 14584	    let (raw, expected_error) = match category {
 14585	        "missing-node" => {
 14586	            create.remove("node").context("create-node has no node")?;
 14587	            (serde_json::to_vec(&value)?, "missing field `node`")
 14588	        }
 14589	        "unknown-kind" => {
 14590	            create["node"]["kind"] = serde_json::json!("unknown");
 14591	            (serde_json::to_vec(&value)?, "invalid type")
 14592	        }
 14593	        "cycle" | "external-value" | "comment" => {
 14594	            create["node"]["payload"] = match category {
 14595	                "cycle" => serde_json::json!({ "cycle": ["a", "b", "a"] }),
 14596	                "external-value" => serde_json::json!({ "external-value": "source" }),
 14597	                _ => serde_json::json!({ "comment": "note" }),
 14598	            };
 14599	            (serde_json::to_vec(&value)?, "unknown variant")
 14600	        }
 14601	        "duplicate-id" => {
 14602	            // A JSON object cannot hold a key twice as a Value, so the second
 14603	            // `id` is spliced into the serialized node text.
 14604	            let node = serde_json::to_string(&create["node"])?;
 14605	            let rest = node
 14606	                .strip_prefix('{')
 14607	                .context("serialized node is not an object")?;
 14608	            // The id's SERIALIZED form, not its Display form: the first
 14609	            // version spliced `NodeId`'s Display text (`n…`) and the codec
 14610	            // refused it for a malformed UUID -- a second defect, caught by the
 14611	            // attribution check below.
 14612	            let second_id = serde_json::to_string(&liminal_id::NodeId::from_uuid(rng.uuid()))?;
 14613	            let duplicated = format!(r#"{{"id":{second_id},{rest}"#);
 14614	            create["node"] = serde_json::json!("__A03_NODE__");
 14615	            let text = serde_json::to_string(&value)?.replace(r#""__A03_NODE__""#, &duplicated);
 14616	            (text.into_bytes(), "duplicate field `id`")
 14617	        }
 14618	        other => anyhow::bail!("unknown graph negative category {other}"),
 14619	    };
 14620	    let error = serde_json::from_slice::<liminal_graph::Transaction>(&raw)
 14621	        .err()
 14622	        .with_context(|| format!("graph negative {category} decoded as a Transaction"))?
 14623	        .to_string();
 14624	    anyhow::ensure!(
 14625	        error.contains(expected_error),
 14626	        "graph negative {category} was refused for another reason: expected {expected_error:?}, got {error:?}"
 14627	    );
 14628	    Ok(raw)
 14629	}
