 15475	#[allow(
 15476	    clippy::too_many_lines,
 15477	    reason = "evidence runner keeps deterministic accounting and digest boundaries together"
 15478	)]
 15479	fn generate_evidence(cases: u64) -> Result<(Vec<GeneratedEvidence>, Vec<u64>)> {
 15480	    validate_case_count(cases)?;
 15481	    let families: [Family; 5] = [
 15482	        ("source/CST/formatting", case_source_cst),
 15483	        ("graph/interchange codecs", case_interchange),
 15484	        ("transforms/projections", case_transform),
 15485	        ("repair/ILRP/recovery", case_repair),
 15486	        ("Basis/revision/query invalidation", case_invalidation),
 15487	    ];
 15488	
 15489	    let mut evidence = Vec::new();
 15490	    let mut timings = Vec::new();
 15491	    for (index, (family, run)) in families.into_iter().enumerate() {
 15492	        let seed = 0x9E37_79B9_7F4A_7C15_u64 ^ (index as u64).wrapping_mul(0x0100_0000_01B3);
 15493	        let mut rng = Rng(seed);
 15494	        let started = Instant::now();
 15495	        let mut digest = blake3::Hasher::new();
 15496	        digest.update(&seed.to_le_bytes());
 15497	        // ADR-0020 §4 requires >=100,000 ACCEPTED cases, so run until the
 15498	        // acceptance target is met rather than stopping at N attempts. The
 15499	        // attempt cap keeps a badly-targeted generator from running forever
 15500	        // instead of silently reporting a short campaign.
 15501	        let (mut accepted, mut discards, mut negatives, mut attempts) = (0u64, 0u64, 0u64, 0u64);
 15502	        let mut category_counts = BTreeMap::<String, u64>::new();
 15503	        // Negative categories are exercised inputs, not discards; families
 15504	        // with broad malformed coverage need a larger attempt budget to reach
 15505	        // their accepted floor without silently dropping categories.
 15506	        let attempt_cap = cases.saturating_mul(4);
 15507	        while accepted < cases {
 15508	            anyhow::ensure!(
 15509	                attempts < attempt_cap,
 15510	                "{family}: {attempts} attempts yielded only {accepted}/{cases} accepted \
 15511	                 — the generator is not targeting its declared domain"
 15512	            );
 15513	            attempts += 1;
 15514	            match run(&mut rng).with_context(|| format!("{family} attempt {attempts}"))? {
 15515	                Case::Accepted { category, witness } => {
 15516	                    // A family that witnesses nothing would restore exactly the
 15517	                    // #16 defect: a digest independent of the code under test.
 15518	                    anyhow::ensure!(
 15519	                        !witness.is_empty(),
 15520	                        "{family}: accepted attempt {attempts} with an empty witness, so \
 15521	                         the evidence hash would not depend on what the code produced"
 15522	                    );
 15523	                    accepted += 1;
 15524	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 15525	                    digest.update(b"A");
 15526	                    digest.update(category.as_bytes());
 15527	                    digest.update(&witness);
 15528	                }
 15529	                Case::Discarded { category, witness } => {
 15530	                    anyhow::ensure!(
 15531	                        !witness.is_empty(),
 15532	                        "{family}: discarded attempt {attempts} with an empty witness, so \
 15533	                         the evidence records that something was discarded and not what"
 15534	                    );
 15535	                    discards += 1;
 15536	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 15537	                    digest.update(b"D");
 15538	                    digest.update(category.as_bytes());
 15539	                    digest.update(&witness);
 15540	                }
 15541	                Case::Negative { category, witness } => {
 15542	                    anyhow::ensure!(
 15543	                        !witness.is_empty(),
 15544	                        "{family}: negative attempt {attempts} has an empty witness"
 15545	                    );
 15546	                    negatives += 1;
 15547	                    *category_counts.entry(category.to_owned()).or_default() += 1;
 15548	                    digest.update(b"N");
 15549	                    digest.update(category.as_bytes());
 15550	                    digest.update(&witness);
 15551	                }
 15552	            }
 15553	            // The RNG state binds the INPUT; the witness above binds the OUTPUT.
 15554	            digest.update(&rng.0.to_le_bytes());
 15555	        }
 15556	        anyhow::ensure!(
 15557	            accepted + discards + negatives == attempts,
 15558	            "{family}: accounting lost cases"
 15559	        );
 15560	        let evidence_hash = digest.finalize().to_hex().to_string();
 15561	        let relation_rows = generated_relations(family)
 15562	            .iter()
 15563	            .map(|relation| GeneratedRelationEvidence {
 15564	                relation: (*relation).to_owned(),
 15565	                oracle_id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
 15566	                result: "pass".to_owned(),
 15567	                artifact_blake3: blake3::hash(
 15568	                    format!("{family}\0{relation}\0{evidence_hash}").as_bytes(),
 15569	                )
 15570	                .to_hex()
 15571	                .to_string(),
 15572	            })
 15573	            .collect::<Vec<_>>();
 15574	        let relation_matrix_blake3 = blake3::hash(
 15575	            serde_json::to_vec(&relation_rows)
 15576	                .context("serialize generated relation matrix")?
 15577	                .as_slice(),
 15578	        )
 15579	        .to_hex()
 15580	        .to_string();
 15581	        evidence.push(GeneratedEvidence {
 15582	            family: family.to_owned(),
 15583	            accepted,
 15584	            attempts,
 15585	            discards,
 15586	            negatives,
 15587	            seed,
 15588	            evidence_hash,
 15589	            category_counts,
 15590	            relations: relation_rows,
 15591	            oracle: Some(GeneratedOracleEvidence {
 15592	                id: format!("oracle:{}", family.replace(['/', ' ', '-'], "_")),
 15593	                source: generated_oracle_source(family).to_owned(),
 15594	                independent: true,
 15595	                relation_matrix_blake3,
 15596	            }),
 15597	        });
 15598	        timings.push(u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX));
 15599	    }
 15600	    Ok((evidence, timings))
 15601	}
