14437	fn case_source_cst(rng: &mut Rng) -> Result<Case> {
14438	    // Blind pass 1 at aa00d41 (A01): a formatter error became a Negative case
14439	    // whatever the category, so a formatter that lost support for nested or
14440	    // deep documents reclassified them as negatives and the run still reached
14441	    // its accepted target from the categories that still worked. Only the
14442	    // categories that DECLARE malformed input may be refused.
14443	    const REFUSABLE: [&str; 5] = [
14444	        "truncated",
14445	        "unterminated",
14446	        "control-byte",
14447	        "invalid-utf8",
14448	        "hostile",
14449	    ];
14450	    let category = rng.category("source/CST/formatting");
14451	    let token = rng.word();
14452	    let bytes = match category {
14453	        "empty" => Vec::new(),
14454	        "single-token" => token.as_bytes().to_vec(),
14455	        "whitespace" => b" \t\n".to_vec(),
14456	        "unicode" => format!("{token} βeta").into_bytes(),
14457	        "long-line" => format!("{}-{token}", token.repeat(64)).into_bytes(),
14458	        "truncated" => format!("{token} {{#").into_bytes(),
14459	        "unterminated" => format!("{token} {{#{token}").into_bytes(),
14460	        "nested" => format!("{token} {{#outer {{#{token}}}}}").into_bytes(),
14461	        "deep" => format!("{} {token}", "{#".repeat(24)).into_bytes(),
14462	        // Blind pass 1 at `2bba9071` (A01): `boundary-offset` renders two
14463	        // blocks with IDENTICAL text, which a constant hash satisfies — it
14464	        // passes the equal-text arm and never meets the other. This renders
14465	        // two blocks of DIFFERENT width, so a hash that ignores its bytes
14466	        // collides across them and the relation has both arms to check. A
14467	        // durable marker cannot be used for this: the formatter lifts `{#id}`
14468	        // into an attribute, which moves a word and reads as reordering.
14469	        "wide" => {
14470	            let row = |count: usize| {
14471	                (0..count)
14472	                    .map(|_| token.clone())
14473	                    .collect::<Vec<_>>()
14474	                    .join(" ")
14475	            };
