14949	fn case_transform_category(category: &'static str, rng: &mut Rng) -> Result<Case> {
14950	    use liminal_source::merge::three_way;
14951	
14952	    if matches!(category, "empty" | "invalid-span" | "truncated" | "hostile") {
14953	        // Negative inputs still cross the production merge implementation.
14954	        // Blind pass 1 at 612cbcc (A03): every category used to become an
14955	        // ordinary label string, so the "negative" tested only the generator's
14956	        // branch. Each category now constructs the shape it names.
14957	        let malformed = transform_negative_input(category, rng);
14958	        let outcome = three_way("{#negative}", &malformed, "{#negative}");
14959	        // Totality is the property: the merge returned rather than panicked.
14960	        // A disjoint outcome must carry the malformed side verbatim; any other
14961	        // outcome class is the transform refusing the shape, recorded as such.
14962	        if let liminal_source::merge::MergeOutcome::Disjoint { merged } = &outcome {
14963	            // The merge normalizes layout (base slot order, block spacing), so
14964	            // verbatim containment is not the property; every token of the
14965	            // malformed side surviving is.
14966	            let mut missing = malformed.split_whitespace().collect::<Vec<_>>();
14967	            for token in merged.split_whitespace() {
14968	                if let Some(index) = missing.iter().position(|m| *m == token) {
14969	                    missing.swap_remove(index);
14970	                }
14971	            }
14972	            anyhow::ensure!(
14973	                missing.is_empty(),
14974	                "transform negative category {category} lost malformed input tokens {missing:?}"
14975	            );
14976	        }
14977	        let witness = format!("transform-negative:{category}:{outcome:?}").into_bytes();
14978	        return Ok(Case::Negative { category, witness });
14979	    }
14980	    let blocks = match category {
14981	        "commute" => 2 + rng.below(3),
14982	        "deep" => 12,
14983	        "wide" | "large-patch" => 8,
14984	        _ => 1 + rng.below(4),
14985	    };
14986	    let base = (0..blocks)
14987	        .map(|i| format!("{} {{#b{i}}}", rng.word()))
14988	        .collect::<Vec<_>>()
14989	        .join("\n\n");
14990	    // Out of domain: a degenerate base has no slots to align.
14991	    if base.trim().is_empty() {
14992	        return Ok(Case::Negative {
14993	            category,
14994	            witness: format!("degenerate-base:{base:?}").into_bytes(),
14995	        });
14996	    }
14997	    let token = rng.word();
14998	    let (ours, theirs) = source_transform_edits(category, &base, &token)?;
14999	
15000	    // Identity: theirs unchanged => the merge must carry ours' content.
15001	    //
15002	    // M17.5 pass-2 #9: this used to be `if let Disjoint { merged } = ...`, so an
15003	    // implementation that returned `Conflict` for EVERY input never entered the
15004	    // branch and the relation held vacuously — the metamorphic check tested
15005	    // nothing at all. A side that changed nothing cannot conflict with anything,
15006	    // so `Disjoint` is a REQUIREMENT here, not a case to handle.
15007	    let identity = three_way(&base, &ours, &base);
15008	    let forward = three_way(&base, &ours, &theirs);
15009	    let swapped = three_way(&base, &theirs, &ours);
15010	    let witness = independent_oracle_source_transform(
15011	        category, &base, &ours, &theirs, &identity, &forward, &swapped,
15012	    )?;
15013	    Ok(Case::Accepted { category, witness })
15014	}
15015	
15016	fn source_transform_edits(category: &str, base: &str, token: &str) -> Result<(String, String)> {
15017	    let mut lines = base.lines().map(str::to_owned).collect::<Vec<_>>();
15018	    let first = lines.first().cloned().unwrap_or_default();
15019	    let second = base
15020	        .split("\n\n")
15021	        .nth(1)
15022	        .map_or_else(|| first.clone(), str::to_owned);
15023	    anyhow::ensure!(
15024	        category != "commute" || base.split("\n\n").count() >= 2,
15025	        "commuting source edits require two distinct base blocks"
15026	    );
15027	    Ok(match category {
15028	        "identity" | "deep" | "wide" | "large-patch" => (base.to_owned(), base.to_owned()),
15029	        "insert" => (format!("{token}\n\n{base}"), base.to_owned()),
15030	        "delete" => (
15031	            lines.iter().skip(1).cloned().collect::<Vec<_>>().join("\n"),
15032	            base.to_owned(),
15033	        ),
15034	        "replace" => (
15035	            base.replacen(&first, &format!("{token} {first}"), 1),
15036	            base.to_owned(),
15037	        ),
15038	        "move" => {
15039	            lines.reverse();
15040	            (lines.join("\n"), base.to_owned())
15041	        }
15042	        "overlap" => (
15043	            base.replacen(&first, &format!("ours {first}"), 1),
15044	            base.replacen(&first, &format!("theirs {first}"), 1),
15045	        ),
15046	        "commute" => (
15047	            base.replacen(&first, &format!("ours {first}"), 1),
15048	            base.replacen(&second, &format!("theirs {second}"), 1),
15049	        ),
15050	        "conflict" => (
15051	            base.replacen(&first, &format!("left {first}"), 1),
15052	            base.replacen(&first, &format!("right {first}"), 1),
15053	        ),
15054	        "boundary-span" => (format!("\n{base}\n"), base.to_owned()),
15055	        other => unreachable!("unknown transform category {other}"),
15056	    })
15057	}
