15059	/// Family 3 — repair/ILRP/recovery.
15060	///
15061	/// Builds a real `RepairPlan` DAG and orders it. Metamorphic relation:
15062	/// **deterministic permutation** — shuffling the dependency list must not
15063	/// change the resulting order. The ordering is then verified against the
15064	/// generator's OWN edge set, not by asking the implementation again. Cyclic
15065	/// candidates are out of domain and are discarded, which is where this
15066	/// family's discard rate genuinely comes from.
15067	#[allow(
15068	    clippy::too_many_lines,
15069	    reason = "repair generator keeps ILRP probe, DAG construction, and oracle witness together"
15070	)]
15071	fn case_repair(rng: &mut Rng) -> Result<Case> {
15072	    use liminal_jurisdiction::repair::{
15073	        ProposedMutation, RepairDependency, RepairOperation, RepairPlan, StatePredicate, topo_order,
15074	    };
15075	
15076	    let category = rng.category("repair/ILRP/recovery");
15077	    let probe = generated_ilrp_probe()?;
15078	    let state_witness = match category {
15079	        "applying" => liminal_jurisdiction::IntentState::Applying,
15080	        "external-applied" => liminal_jurisdiction::IntentState::ExternalApplied,
15081	        "finalizing" => liminal_jurisdiction::IntentState::Finalizing,
15082	        "committed" => liminal_jurisdiction::IntentState::Committed,
15083	        "needs-review" | "contested" => liminal_jurisdiction::IntentState::NeedsReview,
15084	        "boundary" => liminal_jurisdiction::IntentState::Aborted,
15085	        _ => liminal_jurisdiction::IntentState::Prepared,
15086	    };
15087	    let legal_next = match state_witness {
15088	        liminal_jurisdiction::IntentState::Prepared => liminal_jurisdiction::IntentState::Applying,
15089	        liminal_jurisdiction::IntentState::Applying => {
15090	            liminal_jurisdiction::IntentState::ExternalApplied
15091	        }
15092	        liminal_jurisdiction::IntentState::ExternalApplied => {
15093	            liminal_jurisdiction::IntentState::Finalizing
15094	        }
15095	        liminal_jurisdiction::IntentState::Finalizing => {
15096	            liminal_jurisdiction::IntentState::Committed
15097	        }
15098	        _ => liminal_jurisdiction::IntentState::Committed,
15099	    };
15100	    anyhow::ensure!(
15101	        state_witness.is_terminal() || state_witness.may_transition_to(legal_next),
15102	        "declared ILRP state has no legal transition"
15103	    );
15104	    // Blind pass 1 at f360e90 (A01): every category built WriteFile steps whose
15105	    // contents carried the category's name. Each category now builds the
15106	    // shape it names; the refusal categories are refused by `topo_order`
15107	    // itself and recorded as negatives below.
15108	    let count = match category {
15109	        "two-step" => 2,
15110	        "boundary" => 6,
15111	        _ => usize::try_from(2 + rng.below(5)).expect("step count fits"),
15112	    };
15113	    let ids: Vec<liminal_id::RepairStepId> = (0..count)
15114	        .map(|_| liminal_id::RepairStepId::from_uuid(rng.uuid()))
15115	        .collect();
15116	    let steps: BTreeMap<_, _> = ids
15117	        .iter()
15118	        .map(|id| {
15119	            let contents = match category {
15120	                "hostile" => {
15121	                    let mut bytes = format!("{}\0\u{202e}", rng.word()).into_bytes();
15122	                    bytes.extend(std::iter::repeat_n(0xff_u8, 65_536));
15123	                    bytes
15124	                }
15125	                _ => rng.word().into_bytes(),
15126	            };
15127	            let path = liminal_id::PathId(if category == "hostile" {
15128	                "../../etc/passwd\0".into()
15129	            } else {
15130	                "generated.md".into()
15131	            });
15132	            let operation = if category == "graph-step" {
15133	                RepairOperation::Graph(liminal_graph::Operation::CreateNode {
15134	                    node: liminal_graph::Node {
15135	                        id: liminal_id::NodeId::from_uuid(rng.uuid()),
15136	                        kind: liminal_graph::KindId(1),
15137	                        payload: liminal_graph::PayloadRef::Text(
15138	                            String::from_utf8_lossy(&contents).into_owned(),
15139	                        ),
15140	                        revision: liminal_id::RevisionId(0),
15141	                        flags: liminal_graph::NodeFlags::default(),
15142	                    },
15143	                })
15144	            } else {
15145	                RepairOperation::WriteFile {
15146	                    path: path.clone(),
15147	                    contents: contents.clone(),
15148	                }
15149	            };
