15159	                *id,
15160	                ProposedMutation {
15161	                    id: *id,
15162	                    subject: liminal_id::JurisdictionSubject::Node(liminal_id::NodeId::from_uuid(
15163	                        rng.uuid(),
15164	                    )),
15165	                    operation,
15166	                    expected_prestate: StatePredicate::Any,
15167	                    expected_poststate,
15168	                    idempotency_key: liminal_id::IdempotencyKey::from_uuid(rng.uuid()),
15169	                },
15170	            )
15171	        })
15172	        .collect();
15173	
15174	    let mut edges = Vec::new();
15175	    if category == "two-step" {
15176	        edges.push((0, 1));
15177	    } else {
15178	        for i in 0..count {
15179	            for j in (i + 1)..count {
15180	                if rng.below(3) == 0 {
15181	                    edges.push((i, j));
15182	                }
15183	            }
15184	        }
15185	    }
