15198	        edges.push((count - 1, 0));
15199	    }
15200	    let mut dependencies: Vec<RepairDependency> = edges
15201	        .iter()
15202	        .map(|(before, after)| RepairDependency {
15203	            before: ids[*before],
15204	            after: ids[*after],
15205	        })
15206	        .collect();
15207	    let mut steps = steps;
15208	    match category {
15209	        // A dependency on a step the plan never declares.
15210	        "missing-step" => dependencies.push(RepairDependency {
15211	            before: ids[0],
15212	            after: liminal_id::RepairStepId::from_uuid(rng.uuid()),
15213	        }),
15214	        // The plan's steps were cut short while its dependencies still name
15215	        // the lost tail.
15216	        "truncated-intent" => {
15217	            let lost = ids[count - 1];
15218	            dependencies.push(RepairDependency {
15219	                before: ids[0],
15220	                after: lost,
15221	            });
15222	            steps.remove(&lost);
15223	        }
15224	        _ => {}
15225	    }
15226	    let plan = RepairPlan {
15227	        id: liminal_id::RepairId::from_uuid(rng.uuid()),
15228	        basis: liminal_revision::WorkspaceBasis {
15229	            transaction: liminal_id::TransactionId::from_uuid(rng.uuid()),
15230	            perspective: liminal_revision::BasisPerspective::DurableOnly,
15231	            components: BTreeMap::new(),
15232	        },
15233	        steps,
15234	        dependencies: dependencies.clone(),
15235	        inverse: None,
15236	    };
15237	    let order = match topo_order(&plan) {
15238	        Ok(order) => order,
15239	        Err(error) => {
15240	            // Refused plans are not acceptance evidence. The witness carries
15241	            // the EDGES and the refusal, so the shape reaches the digest —
15242	            // without it every refusal looks alike (M17.5 F-30). A category
15243	            // that promised a refusal gets a negative; a random cycle in an
15244	            // accepted category is out of domain.
15245	            let witness = [
15246	                format!("refused:{error}:{edges:?}:{state_witness:?}:"),
15247	                String::from_utf8_lossy(probe).into_owned(),
15248	            ]
15249	            .concat()
15250	            .into_bytes();
15251	            let promised = match category {
15252	                "cycle" => matches!(
15253	                    error,
15254	                    liminal_jurisdiction::repair::CycleError::Cycle { .. }
15255	                ),
15256	                "missing-step" | "truncated-intent" => {
15257	                    matches!(
15258	                        error,
15259	                        liminal_jurisdiction::repair::CycleError::UnknownStep { .. }
15260	                    )
15261	                }
15262	                _ => false,
15263	            };
15264	            return Ok(if promised {
15265	                Case::Negative { category, witness }
15266	            } else if matches!(category, "cycle" | "missing-step" | "truncated-intent") {
15267	                anyhow::bail!(
15268	                    "repair category {category} was refused for the wrong reason: {error}"
15269	                )
15270	            } else {
15271	                Case::Discarded { category, witness }
15272	            });
15273	        }
15274	    };
15275	    anyhow::ensure!(
15276	        !matches!(category, "missing-step" | "truncated-intent"),
15277	        "repair category {category} promised a refusal and was ordered instead"
15278	    );
15279	    anyhow::ensure!(
15280	        !cyclic,
15281	        "a cyclic plan was ordered instead of refused: {dependencies:?}"
15282	    );
15283	
15284	    // Deterministic permutation: reversing the edge list must not change it.
15285	    let mut permuted = plan.clone();
15286	    permuted.dependencies.reverse();
15287	    let permuted_order = topo_order(&permuted).map_err(|e| anyhow::anyhow!("{e}"))?;
15288	    let mut witness = independent_oracle_source_repair(&order, &ids, &edges, &permuted_order)?;
15289	    witness.extend_from_slice(format!("{state_witness:?}").as_bytes());
15290	    witness.extend_from_slice(probe);
