15311	        "published" => BasisPerspective::Published {
15312	            revision: liminal_id::PublicationId::from_uuid(rng.uuid()),
15313	        },
15314	        "federated" => BasisPerspective::Federated {
15315	            domain: liminal_id::FederationId::from_uuid(rng.uuid()),
