15323	        transaction: liminal_id::TransactionId::from_uuid(rng.uuid()),
15324	        perspective,
15325	        components: if category == "empty-basis" {
15326	            BTreeMap::new()
15327	        } else {
15328	            BTreeMap::from([(
15329	                liminal_revision::graph_key(),
15330	                BasisComponent::GraphSnapshot {
