14991	    if base.trim().is_empty() {
14992	        return Ok(Case::Negative {
14993	            category,
14994	            witness: format!("degenerate-base:{base:?}").into_bytes(),
14995	        });
14996	    }
14997	    let token = rng.word();
14998	    let (ours, theirs) = source_transform_edits(category, &base, &token)?;
