14920	/// Family 2 — transforms/projections.
14921	///
14922	/// Metamorphic relations, both independent of the merge's own equality:
14923	/// **identity** (a side that changed nothing must not perturb the other
14924	/// side's content) and **outcome-class symmetry** (swapping `ours`/`theirs`
14925	/// cannot change whether the merge was structurally disjoint).
14926	/// The input a transform negative category names (A03). `empty` is the empty
14927	/// side; `invalid-span` is a marker that never closes and one with whitespace
14928	/// inside; `truncated` is a block cut in the middle of its marker; `hostile`
14929	/// carries a NUL, a bidi override, a nested marker and an over-long marker.
14930	fn transform_negative_input(category: &str, rng: &mut Rng) -> String {
14931	    let word = rng.word();
14932	    match category {
14933	        "empty" => String::new(),
14934	        "invalid-span" => format!("{word} {{#open\n\n{word} {{# spaced }}"),
14935	        "truncated" => format!("{word} {{#full}}\n\n{word} {{#cu"),
14936	        "hostile" => format!(
14937	            "{word}\0 {{#\u{202e}}} {{#{{#nested}}}} {{#{}}}",
14938	            "x".repeat(4096)
14939	        ),
14940	        other => format!("{other}:{word}"),
14941	    }
14942	}
