15059	/// Family 3 — repair/ILRP/recovery.
15060	///
15061	/// Builds a real `RepairPlan` DAG and orders it. Metamorphic relation:
15062	/// **deterministic permutation** — shuffling the dependency list must not
15063	/// change the resulting order. The ordering is then verified against the
15064	/// generator's OWN edge set, not by asking the implementation again. Cyclic
15065	/// candidates are out of domain and are discarded, which is where this
15066	/// family's discard rate genuinely comes from.
15067	#[allow(
15068	    clippy::too_many_lines,
15069	    reason = "repair generator keeps ILRP probe, DAG construction, and oracle witness together"
15070	)]
15071	fn case_repair(rng: &mut Rng) -> Result<Case> {
15072	    use liminal_jurisdiction::repair::{
15073	        ProposedMutation, RepairDependency, RepairOperation, RepairPlan, StatePredicate, topo_order,
15074	    };
15075	
15076	    let category = rng.category("repair/ILRP/recovery");
15077	    let probe = generated_ilrp_probe()?;
15078	    let state_witness = match category {
15079	        "applying" => liminal_jurisdiction::IntentState::Applying,
15080	        "external-applied" => liminal_jurisdiction::IntentState::ExternalApplied,
15081	        "finalizing" => liminal_jurisdiction::IntentState::Finalizing,
15082	        "committed" => liminal_jurisdiction::IntentState::Committed,
15083	        "needs-review" | "contested" => liminal_jurisdiction::IntentState::NeedsReview,
15084	        "boundary" => liminal_jurisdiction::IntentState::Aborted,
15085	        _ => liminal_jurisdiction::IntentState::Prepared,
15086	    };
15087	    let legal_next = match state_witness {
15088	        liminal_jurisdiction::IntentState::Prepared => liminal_jurisdiction::IntentState::Applying,
15089	        liminal_jurisdiction::IntentState::Applying => {
15090	            liminal_jurisdiction::IntentState::ExternalApplied
15091	        }
15092	        liminal_jurisdiction::IntentState::ExternalApplied => {
15093	            liminal_jurisdiction::IntentState::Finalizing
15094	        }
15095	        liminal_jurisdiction::IntentState::Finalizing => {
15096	            liminal_jurisdiction::IntentState::Committed
15097	        }
15098	        _ => liminal_jurisdiction::IntentState::Committed,
15099	    };
15100	    anyhow::ensure!(
15101	        state_witness.is_terminal() || state_witness.may_transition_to(legal_next),
15102	        "declared ILRP state has no legal transition"
15103	    );
15104	    // Blind pass 1 at f360e90 (A01): every category built WriteFile steps whose
15105	    // contents carried the category's name. Each category now builds the
15106	    // shape it names; the refusal categories are refused by `topo_order`
15107	    // itself and recorded as negatives below.
15108	    let count = match category {
15109	        "two-step" => 2,
15110	        "boundary" => 6,
15111	        _ => usize::try_from(2 + rng.below(5)).expect("step count fits"),
15112	    };
15113	    let ids: Vec<liminal_id::RepairStepId> = (0..count)
15114	        .map(|_| liminal_id::RepairStepId::from_uuid(rng.uuid()))
15115	        .collect();
15116	    let steps: BTreeMap<_, _> = ids
15117	        .iter()
15118	        .map(|id| {
15119	            let contents = match category {
15120	                "hostile" => {
15121	                    let mut bytes = format!("{}\0\u{202e}", rng.word()).into_bytes();
15122	                    bytes.extend(std::iter::repeat_n(0xff_u8, 65_536));
15123	                    bytes
15124	                }
15125	                _ => rng.word().into_bytes(),
15126	            };
15127	            let path = liminal_id::PathId(if category == "hostile" {
15128	                "../../etc/passwd\0".into()
15129	            } else {
15130	                "generated.md".into()
15131	            });
15132	            let operation = if category == "graph-step" {
15133	                RepairOperation::Graph(liminal_graph::Operation::CreateNode {
15134	                    node: liminal_graph::Node {
15135	                        id: liminal_id::NodeId::from_uuid(rng.uuid()),
15136	                        kind: liminal_graph::KindId(1),
15137	                        payload: liminal_graph::PayloadRef::Text(
15138	                            String::from_utf8_lossy(&contents).into_owned(),
15139	                        ),
15140	                        revision: liminal_id::RevisionId(0),
15141	                        flags: liminal_graph::NodeFlags::default(),
15142	                    },
15143	                })
15144	            } else {
15145	                RepairOperation::WriteFile {
15146	                    path: path.clone(),
15147	                    contents: contents.clone(),
15148	                }
15149	            };
15150	            let expected_poststate = if category == "poststate" {
15151	                StatePredicate::FileContent {
15152	                    path,
15153	                    hash: liminal_id::ContentHash(*blake3::hash(&contents).as_bytes()),
15154	                }
15155	            } else {
15156	                StatePredicate::Any
15157	            };
15158	            (
15159	                *id,
15160	                ProposedMutation {
15161	                    id: *id,
15162	                    subject: liminal_id::JurisdictionSubject::Node(liminal_id::NodeId::from_uuid(
15163	                        rng.uuid(),
15164	                    )),
15165	                    operation,
15166	                    expected_prestate: StatePredicate::Any,
15167	                    expected_poststate,
15168	                    idempotency_key: liminal_id::IdempotencyKey::from_uuid(rng.uuid()),
15169	                },
15170	            )
15171	        })
15172	        .collect();
15173	
15174	    let mut edges = Vec::new();
15175	    if category == "two-step" {
15176	        edges.push((0, 1));
15177	    } else {
15178	        for i in 0..count {
15179	            for j in (i + 1)..count {
15180	                if rng.below(3) == 0 {
15181	                    edges.push((i, j));
15182	                }
15183	            }
15184	        }
15185	    }
15186	    if category == "duplicate-ack" {
15187	        // The same dependency acknowledged twice: the plan orders as if once.
15188	        let first = edges.first().copied().unwrap_or((0, 1));
15189	        edges.push(first);
15190	        edges.push(first);
15191	    }
15192	    // Rarely close a genuine cycle. A lone back edge is NOT a cycle unless a
15193	    // forward path exists, so add both directions to guarantee one.
15194	    let cyclic = count >= 2 && (category == "cycle" || rng.below(384) == 0);
15195	    if cyclic {
15196	        edges.retain(|(before, after)| !(*before == 0 && *after == count - 1));
15197	        edges.push((0, count - 1));
15198	        edges.push((count - 1, 0));
15199	    }
15200	    let mut dependencies: Vec<RepairDependency> = edges
15201	        .iter()
15202	        .map(|(before, after)| RepairDependency {
15203	            before: ids[*before],
15204	            after: ids[*after],
15205	        })
15206	        .collect();
15207	    let mut steps = steps;
15208	    match category {
15209	        // A dependency on a step the plan never declares.
15210	        "missing-step" => dependencies.push(RepairDependency {
15211	            before: ids[0],
15212	            after: liminal_id::RepairStepId::from_uuid(rng.uuid()),
15213	        }),
15214	        // The plan's steps were cut short while its dependencies still name
15215	        // the lost tail.
15216	        "truncated-intent" => {
15217	            let lost = ids[count - 1];
15218	            dependencies.push(RepairDependency {
15219	                before: ids[0],
15220	                after: lost,
15221	            });
15222	            steps.remove(&lost);
15223	        }
15224	        _ => {}
15225	    }
15226	    let plan = RepairPlan {
15227	        id: liminal_id::RepairId::from_uuid(rng.uuid()),
15228	        basis: liminal_revision::WorkspaceBasis {
15229	            transaction: liminal_id::TransactionId::from_uuid(rng.uuid()),
15230	            perspective: liminal_revision::BasisPerspective::DurableOnly,
15231	            components: BTreeMap::new(),
15232	        },
15233	        steps,
15234	        dependencies: dependencies.clone(),
15235	        inverse: None,
15236	    };
15237	    let order = match topo_order(&plan) {
15238	        Ok(order) => order,
15239	        Err(error) => {
15240	            // Refused plans are not acceptance evidence. The witness carries
15241	            // the EDGES and the refusal, so the shape reaches the digest —
15242	            // without it every refusal looks alike (M17.5 F-30). A category
15243	            // that promised a refusal gets a negative; a random cycle in an
15244	            // accepted category is out of domain.
15245	            let witness = [
15246	                format!("refused:{error}:{edges:?}:{state_witness:?}:"),
15247	                String::from_utf8_lossy(probe).into_owned(),
15248	            ]
15249	            .concat()
15250	            .into_bytes();
15251	            let promised = match category {
15252	                "cycle" => matches!(
15253	                    error,
15254	                    liminal_jurisdiction::repair::CycleError::Cycle { .. }
15255	                ),
15256	                "missing-step" | "truncated-intent" => {
15257	                    matches!(
15258	                        error,
15259	                        liminal_jurisdiction::repair::CycleError::UnknownStep { .. }
15260	                    )
15261	                }
15262	                _ => false,
15263	            };
15264	            return Ok(if promised {
15265	                Case::Negative { category, witness }
15266	            } else if matches!(category, "cycle" | "missing-step" | "truncated-intent") {
15267	                anyhow::bail!(
15268	                    "repair category {category} was refused for the wrong reason: {error}"
15269	                )
15270	            } else {
15271	                Case::Discarded { category, witness }
15272	            });
15273	        }
15274	    };
15275	    anyhow::ensure!(
15276	        !matches!(category, "missing-step" | "truncated-intent"),
15277	        "repair category {category} promised a refusal and was ordered instead"
15278	    );
15279	    anyhow::ensure!(
15280	        !cyclic,
15281	        "a cyclic plan was ordered instead of refused: {dependencies:?}"
15282	    );
15283	
15284	    // Deterministic permutation: reversing the edge list must not change it.
15285	    let mut permuted = plan.clone();
15286	    permuted.dependencies.reverse();
15287	    let permuted_order = topo_order(&permuted).map_err(|e| anyhow::anyhow!("{e}"))?;
15288	    let mut witness = independent_oracle_source_repair(&order, &ids, &edges, &permuted_order)?;
15289	    witness.extend_from_slice(format!("{state_witness:?}").as_bytes());
15290	    witness.extend_from_slice(probe);
15291	    Ok(Case::Accepted { category, witness })
15292	}
