3221	                .split(';')
3222	                .map(|phrase| phrase.trim().to_ascii_lowercase())
3223	                .filter(|phrase| !phrase.is_empty())
3224	                .collect(),
3225	            status,
3226	            file: relative_file,
3227	        });
3228	    }
3229	    Ok(out)
3230	}
