3232	fn validate_ruling_coordinate(target: &str) -> Result<()> {
3233	    let (path, line) = target
3234	        .rsplit_once(':')
3235	        .context("target is not a repository path:positive-line coordinate")?;
3236	    anyhow::ensure!(
3237	        canonical_relative_path(path) && !path.contains(':') && !path.contains('\\'),
3238	        "target path is not canonical"
3239	    );
3240	    anyhow::ensure!(
3241	        !line.is_empty()
3242	            && line.bytes().all(|byte| byte.is_ascii_digit())
3243	            && (line == "0" || !line.starts_with('0'))
3244	            && line.parse::<usize>().is_ok_and(|value| value > 0),
3245	        "target line must be a canonical positive decimal"
3246	    );
