3250	fn canonical_relative_path(path: &str) -> bool {
3251	    !path.is_empty()
3252	        && !path.starts_with('/')
3253	        && Path::new(path)
3254	            .components()
3255	            .all(|component| matches!(component, Component::Normal(_)))
3256	        && path
3257	            .split('/')
3258	            .all(|component| !component.is_empty() && component != "." && component != "..")
