2725	/// A reviewer cannot make its own "independent reproduction" true by setting
2726	/// two booleans in one record. Every reproduced finding must have one matching
2727	/// verified defect in the other isolated pass, with the same attack class,
2728	/// exact source target, and identical falsification claim/observation. This
2729	/// prevents two semantically different reports at one line from becoming a
2730	/// concurrence by coordinate coincidence; finding IDs remain pass-local.
2731	/// Whether two blinded passes are reporting the same defect. Blind pass 1 at
2732	/// `0a0b4b4b` (A10): this required the `attempt` and `observed_result` strings
2733	/// to be byte-identical. Two reviewers who cannot see each other's work will
2734	/// not write the same sentence, so a genuine independent reproduction was
2735	/// rejected unless they coordinated wording — which is the one thing the
2736	/// blinding exists to prevent. The class and the coordinate already match by
2737	/// the time this is asked; what is left to establish is that the two are about
2738	/// the same thing, and shared vocabulary establishes it. Four significant
2739	/// words in common is far more than coincidence at one coordinate and far less
2740	/// than dictation.
2741	fn reports_the_same_defect(
2742	    left: &ReviewRecordAttempt,
2743	    right: &ReviewRecordAttempt,
2744	    corpus: &[&ReviewRecordAttempt],
2745	    source_vocabulary: Option<&BTreeSet<String>>,
2746	) -> bool {
2747	    // Blind pass 1 at `ec045588` (A02): both reports name the coordinate, so
2748	    // `crates`, `liminal`, `xtask` and `haq` were four shared words before
2749	    // either said anything — the coordinate matched twice, once as itself and
2750	    // once as vocabulary. Words the coordinate already carries are struck out,
2751	    // and so are the handful this campaign puts in every report.
2752	    const UBIQUITOUS: [&str; 8] = [
2753	        "verifier",
2754	        "verify",
2755	        "packet",
2756	        "evidence",
2757	        "check",
2758	        "checks",
2759	        "because",
2760	        "committed",
2761	    ];
2762	    let coordinate: BTreeSet<String> = format!("{} {}", left.target, right.target)
2763	        .to_ascii_lowercase()
2764	        .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2765	        .map(str::to_owned)
2766	        .collect();
2767	    let vocabulary = |attempt: &ReviewRecordAttempt| {
2768	        format!("{} {}", attempt.attempt, attempt.observed_result)
2769	            .to_ascii_lowercase()
2770	            .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2771	            .filter(|word| word.len() >= 4)
2772	            .filter(|word| !coordinate.contains(*word))
2773	            .filter(|word| !UBIQUITOUS.contains(word))
2774	            .map(str::to_owned)
2775	            .collect::<BTreeSet<_>>()
2776	    };
2777	    let shared: BTreeSet<String> = vocabulary(left)
2778	        .intersection(&vocabulary(right))
2779	        .cloned()
2780	        .collect();
2781	    if shared.len() < 4 {
2782	        return false;
2783	    }
2784	    // Blind pass 1 at `2bba9071` (A09): four shared words is a count, and a
2785	    // count is satisfied by four words this campaign puts in every report.
2786	    // What makes two reports the same report is sharing something RARE — a
2787	    // word that does not appear all over the rest of the record. Two such
2788	    // words, measured against every attempt in both passes rather than
2789	    // against a list someone maintains.
2790	    let distinctive = shared
2791	        .iter()
2792	        .filter(|word| {
2793	            // Shared prose is only a concurrence signal when it also names
2794	            // vocabulary present in the cited source. This blocks unrelated
2795	            // reports manufactured from four private nonce words while still
2796	            // allowing independently worded descriptions of real code.
2797	            source_vocabulary.is_none_or(|source| source.contains(word.as_str()))
2798	        })
2799	        .filter(|word| {
2800	            corpus
2801	                .iter()
2802	                .filter(|attempt| {
2803	                    format!("{} {}", attempt.attempt, attempt.observed_result)
2804	                        .to_ascii_lowercase()
2805	                        .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2806	                        .any(|token| token == word.as_str())
2807	                })
2808	                .count()
2809	                <= 2
2810	        })
2811	        .count();
2812	    distinctive >= 2
2813	}
