2815	fn source_vocabulary(root: &Utf8Path, target: &str) -> Result<BTreeSet<String>> {
2816	    let file = target
2817	        .split(':')
2818	        .next()
2819	        .filter(|file| !file.trim().is_empty())
2820	        .context("review target has no source file")?;
2821	    // Resolve through the same repository-bound path guard used by every other
2822	    // review artifact. A missing or escaping target must fail closed; treating
2823	    // it as `None` would silently disable source-grounded concurrence.
2824	    let path = safe_repo_path(root, file, "review target")?;
2825	    let text = fs::read_to_string(&path).with_context(|| format!("read review target {path}"))?;
2826	    Ok(text
2827	        .to_ascii_lowercase()
2828	        .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
2829	        .filter(|word| word.len() >= 4)
2830	        .map(str::to_owned)
2831	        .collect())
2832	}
