2914	/// The record's claims are what the retained answer says (F-92, blind pass 1
2915	/// at `088ddeec`, A12).
2916	///
2917	/// The raw answer and the structured claims were each hashed, and nothing
2918	/// compared them. A record could retain a real answer and carry different
2919	/// attempts, findings or verdict, with every digest true. The runner builds
2920	/// each claim as `redact_deep(parse_json(raw)[field])`
2921	/// (`scripts/haqp_blind_review.py`), so the gate re-derives it the same way
2922	/// from the retained answer, and requires the record to hold exactly that.
2923	fn verify_review_claims_are_the_answer(record_path: &Utf8Path) -> Result<()> {
2924	    let raw_path = record_path.with_extension("raw.txt");
2925	    let raw = fs::read_to_string(&raw_path)
2926	        .with_context(|| format!("{raw_path}: the raw answer must be retained"))?;
2927	    let answer = review_answer_json(&raw)
2928	        .with_context(|| format!("{raw_path}: the retained answer is not a review"))?;
2929	    let record: serde_json::Value = serde_json::from_slice(
2930	        &fs::read(record_path).with_context(|| format!("read {record_path}"))?,
2931	    )
2932	    .with_context(|| format!("parse {record_path}"))?;
2933	    for field in [
2934	        "attempts",
2935	        "findings",
2936	        "independently_reproduced",
2937	        "unresolved_verified_findings",
2938	        "result",
2939	    ] {
2940	        let said = match answer.get(field) {
2941	            Some(value) => value.clone(),
2942	            // `parsed.get("findings", [])`: the runner's one defaulted field.
2943	            None if field == "findings" => serde_json::Value::Array(Vec::new()),
2944	            None => serde_json::Value::Null,
2945	        };
2946	        // The count is copied, not redacted: it is not a string.
2947	        let expected = if field == "unresolved_verified_findings" {
2948	            said
2949	        } else {
2950	            redact_evidence_deep(&said)
2951	        };
2952	        let recorded = record.get(field).unwrap_or(&serde_json::Value::Null);
2953	        anyhow::ensure!(
2954	            *recorded == expected,
2955	            "review record `{field}` is not what the retained answer says; a record's \
2956	             claims are the reviewer's answer, not an edit of it"
2957	        );
2958	    }
2959	    Ok(())
2960	}
