2962	/// The reviewer's JSON, located as the runner's `parse_json` locates it: the
2963	/// whole text, or else the span from the first `{` to the last `}`.
2964	fn review_answer_json(raw: &str) -> Result<serde_json::Value> {
2965	    if let Ok(value) = serde_json::from_str::<serde_json::Value>(raw) {
2966	        return Ok(value);
2967	    }
2968	    let (Some(start), Some(end)) = (raw.find('{'), raw.rfind('}')) else {
2969	        anyhow::bail!("no JSON object in the answer");
2970	    };
2971	    anyhow::ensure!(start < end, "no JSON object in the answer");
2972	    Ok(serde_json::from_str(&raw[start..=end])?)
2973	}
