2992	/// `redact_evidence` from `scripts/haqp_blind_review.py`, which substitutes
2993	/// `****` for each match of its `CREDENTIAL_SHAPED` pattern:
2994	///
2995	/// - a known vendor prefix followed by 12 or more of `[A-Za-z0-9_-]`, or
2996	/// - a run of 24 or more of `[A-Za-z0-9_-]` holding a lowercase letter, an
2997	///   uppercase letter and a digit.
2998	///
2999	/// Both alternatives consume greedily and matching resumes after each match,
3000	/// as `re.sub` does. The second alternative looks ahead over the whole run
3001	/// from its start, so a run that fails it has no suffix that passes.
3002	fn redact_evidence(text: &str) -> String {
3003	    const PREFIXES: [&str; 10] = [
3004	        "sk-", "AIza", "ghp_", "gho_", "xoxb-", "xoxa-", "xoxp-", "xoxr-", "xoxs-", "hf_",
3005	    ];
3006	    let is_key_byte = |b: u8| b.is_ascii_alphanumeric() || b == b'_' || b == b'-';
3007	    let bytes = text.as_bytes();
3008	    let run_from = |at: usize| bytes[at..].iter().take_while(|b| is_key_byte(**b)).count();
3009	    let mut out = String::with_capacity(text.len());
3010	    let mut at = 0;
3011	    while at < bytes.len() {
3012	        let rest = &text[at..];
3013	        let prefixed = PREFIXES.iter().find_map(|prefix| {
3014	            if !rest.starts_with(prefix) {
3015	                return None;
3016	            }
3017	            let tail = run_from(at + prefix.len());
3018	            (tail >= 12).then_some(prefix.len() + tail)
3019	        });
3020	        let shaped = || {
3021	            let run = &bytes[at..at + run_from(at)];
3022	            (run.len() >= 24
3023	                && run.iter().any(u8::is_ascii_lowercase)
3024	                && run.iter().any(u8::is_ascii_uppercase)
3025	                && run.iter().any(u8::is_ascii_digit))
3026	            .then_some(run.len())
3027	        };
3028	        if let Some(len) = prefixed.or_else(shaped) {
3029	            out.push_str("****");
3030	            at += len;
3031	        } else {
3032	            let ch = rest
3033	                .chars()
3034	                .next()
3035	                .expect("at is a char boundary below len");
3036	            out.push(ch);
3037	            at += ch.len_utf8();
3038	        }
3039	    }
3040	    out
3041	}
