2834	fn verify_cross_pass_reproduction(
2835	    root: &Utf8Path,
2836	    records: &[(String, ReviewRecord)],
2837	) -> Result<()> {
2838	    if records.is_empty() {
2839	        return Ok(());
2840	    }
2841	    anyhow::ensure!(
2842	        records.len() == 2,
2843	        "cross-pass reproduction requires two records"
2844	    );
2845	    // Every attempt both passes made, which is what says whether a shared word
2846	    // is rare or is something the campaign writes everywhere (A09).
2847	    let corpus: Vec<&ReviewRecordAttempt> = records
2848	        .iter()
2849	        .flat_map(|(_, record)| record.attempts.iter())
2850	        .collect();
2851	    for (index, (who, record)) in records.iter().enumerate() {
2852	        let other = &records[1 - index].1;
2853	        let findings = review_finding_ids(&record.findings, &record.attempts, who)?;
2854	        for finding_id in &record.independently_reproduced {
2855	            let attempt_id = findings.get(finding_id.as_str()).with_context(|| {
2856	                format!("{who}: reproduced finding {finding_id:?} is not linked")
2857	            })?;
2858	            let attempt = record
2859	                .attempts
2860	                .iter()
2861	                .find(|attempt| attempt.id == *attempt_id)
2862	                .expect("finding linkage validated");
2863	            let source_words = source_vocabulary(root, &attempt.target)?;
2864	            let matches = other
2865	                .attempts
2866	                .iter()
2867	                .filter(|candidate| {
2868	                    candidate.classification == "verified_defect"
2869	                        && candidate.independently_reproduced
2870	                        && candidate.attack_class == attempt.attack_class
2871	                        && candidate.target == attempt.target
2872	                        && reports_the_same_defect(candidate, attempt, &corpus, Some(&source_words))
2873	                })
2874	                .count();
2875	            anyhow::ensure!(
2876	                matches == 1,
2877	                "{who}: reproduced finding {finding_id:?} needs exactly one independently reproduced defect in the other pass with the same attack class, the same source coordinate, and a report about the same defect; found {matches}"
