3261	/// A ruling is in force when its status is `ruled` and the last commit that
3262	/// touched its file verifies against the pinned signers. A draft, an
3263	/// uncommitted edit, or an unsigned commit clears nothing.
3264	fn ruling_in_force(root: &Utf8Path, ruling: &Ruling) -> Result<bool> {
3265	    if ruling.status != "ruled" {
3266	        return Ok(false);
3267	    }
3268	    let signers = root.join(RULING_SIGNERS);
3269	    anyhow::ensure!(
3270	        signers.is_file(),
3271	        "{RULING_SIGNERS} is missing; a ruling cannot be verified against no signer"
3272	    );
3273	    let dirty = git_text(root, &["status", "--porcelain", "--", &ruling.file])?;
3274	    if !dirty.trim().is_empty() {
3275	        return Ok(false);
3276	    }
3277	    let commit = git_text(root, &["log", "-1", "--format=%H", "--", &ruling.file])?;
3278	    if commit.trim().is_empty() {
3279	        return Ok(false);
3280	    }
3281	    let verified = Command::new("git")
3282	        .current_dir(root)
3283	        .args(["-c", "gpg.format=ssh", "-c"])
3284	        .arg(format!("gpg.ssh.allowedSignersFile={signers}"))
3285	        .args(["verify-commit", commit.trim()])
3286	        .output()
3287	        .context("git verify-commit")?;
3288	    Ok(verified.status.success())
3289	}
