3305	/// Whether a verified, unresolved defect blocks qualification (AM-17.20).
3306	///
3307	/// Only S1, a false pass, blocks. A defect is S2 (weak check) or S3
3308	/// (bookkeeping) only when the reviewer both says so and states why a false
3309	/// pass is ruled out, in prose of the same substance every attempt field
3310	/// needs. Anything else, including a missing or unknown class and every record
3311	/// written before the bar existed, is S1. The default runs toward blocking, so
3312	/// a lazy or truncated answer cannot downgrade a finding.
3313	fn finding_blocks(attempt: &serde_json::Value) -> bool {
3314	    let downgraded = matches!(attempt["severity"].as_str(), Some("S2" | "S3"));
3315	    let reason = attempt["false_pass_ruled_out"]
3316	        .as_str()
3317	        .unwrap_or_default()
3318	        .trim();
3319	    let substantive = reason.len() >= 24 && reason.split_whitespace().count() >= 4;
3320	    !(downgraded && substantive)
3321	}
