3323	/// The count, given the rulings already established to be in force. Split from
3324	/// the repository walk so the clearance rules can be exercised without a
3325	/// signing key: a rule the tests cannot reach is a rule nothing checks.
3326	fn effective_unresolved_findings(
3327	    in_force: &[Ruling],
3328	    value: &serde_json::Value,
3329	    record: &Utf8Path,
3330	) -> Result<u64> {
3331	    // Counted from each attempt's own flags, not through the findings list:
3332	    // a verified, reproduced attempt the reviewer forgot to list as a finding
3333	    // is still unresolved.
3334	    let mut unresolved = 0u64;
3335	    let mut cleared: BTreeMap<String, u64> = BTreeMap::new();
3336	    for attempt in value["attempts"].as_array().into_iter().flatten() {
3337	        let class = attempt["attack_class"].as_str().unwrap_or_default();
3338	        let target = attempt["target"].as_str().unwrap_or_default();
3339	        if attempt["classification"].as_str() != Some("verified_defect")
3340	            || !attempt["independently_reproduced"]
3341	                .as_bool()
3342	                .unwrap_or(false)
3343	            || attempt["resolved"].as_bool().unwrap_or(false)
3344	            || !finding_blocks(attempt)
3345	        {
3346	            continue;
3347	        }
3348	        let prose = format!(
3349	            "{} {}",
3350	            attempt["attempt"].as_str().unwrap_or_default(),
3351	            attempt["observed_result"].as_str().unwrap_or_default()
3352	        )
3353	        .to_ascii_lowercase();
3354	        // Blind pass 1 at c29bc0ea (A08): a ruling matched on class, file and
3355	        // prose substrings, so an unrelated defect in the same file whose
3356	        // wording happened to carry the required phrases was cleared in
3357	        // silence. Two things changed. A ruling that names a coordinate is
3358	        // held to it, not merely to the file. And a ruling clears at most one
3359	        // attempt per record: matching a second is evidence the phrases are
3360	        // too broad, and the answer to that is a refusal, not two clearances.
3361	        let matched = in_force
3362	            .iter()
3363	            .filter(|ruling| {
3364	                ruling.attack_class == class
3365	                    && ruling.target == target
3366	                    && ruling
3367	                        .claim_requires
3368	                        .iter()
3369	                        .all(|phrase| prose.contains(phrase.as_str()))
3370	                    && !ruling
3371	                        .claim_excludes
3372	                        .iter()
3373	                        .any(|phrase| prose.contains(phrase.as_str()))
3374	            })
3375	            .collect::<Vec<_>>();
3376	        for ruling in &matched {
3377	            *cleared.entry(ruling.id.clone()).or_insert(0u64) += 1;
3378	        }
3379	        if matched.is_empty() {
3380	            unresolved += 1;
3381	        }
3382	    }
3383	    for (id, count) in &cleared {
3384	        anyhow::ensure!(
3385	            *count <= 1,
3386	            "ruling {id} cleared {count} separate findings in {record}; a ruling \
3387	                 answers one claim, so phrases matching more than one are too \
3388	                 broad to stand"
3389	        );
3390	    }
3391	    Ok(unresolved)
3392	}
