 9523	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
 9524	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
 9525	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
 9526	/// Requirement kinds are closed by the HAQP packet contract. An open kind
 9527	/// vocabulary lets a packet relabel a stateful requirement and evade its
 9528	/// fault/recovery evidence obligations (M17.5 P1-A04).
 9529	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
