 9633	/// M17.5 F-05: ADR-0020 §3 forbids mutation coverage clustering on
 9634	/// easy-to-kill paths. A 100% kill rate carried by a handful of coarse
 9635	/// end-to-end tests measures almost nothing, so cap any one test's share of
 9636	/// the denominator and require every named killer to exist.
 9637	fn verify_kill_concentration(packet: &Packet) -> Result<()> {
 9638	    let total = packet.mutants.len();
 9639	    if total == 0 {
 9640	        return Ok(());
 9641	    }
 9642	    let test_ids = packet
 9643	        .tests
 9644	        .iter()
 9645	        .map(|row| row.id.as_str())
 9646	        .collect::<BTreeSet<_>>();
 9647	    let mut kills = BTreeMap::<&str, usize>::new();
 9648	    for mutant in &packet.mutants {
 9649	        for test in &mutant.killing_tests {
 9650	            if !test_ids.contains(test.as_str()) {
 9651	                anyhow::bail!("{} names unknown killing test {test}", mutant.id);
 9652	            }
 9653	            *kills.entry(test.as_str()).or_default() += 1;
 9654	        }
 9655	    }
 9656	    for (test, count) in &kills {
 9657	        #[allow(clippy::cast_precision_loss, reason = "inventory-scale counts")]
 9658	        let share = *count as f64 / total as f64;
 9659	        // M17.5 F-30: `>` -> `>=` survives here and is EQUIVALENT within the
 9660	        // reachable domain. `share` is `count / total` over 65 declared
 9661	        // mutants, and 65/4 is not an integer, so `share == 0.25` exactly
 9662	        // cannot occur.
 9663	        if share > MAX_KILL_SHARE {
 9664	            anyhow::bail!(
 9665	                "{test} is the named killer for {count}/{total} mutants ({:.0}%), \
 9666	                 above the {:.0}% ceiling — mutation coverage is clustering on one \
 9667	                 coarse test",
 9668	                share * 100.0,
 9669	                MAX_KILL_SHARE * 100.0
 9670	            );
 9671	        }
 9672	    }
 9673	    Ok(())
 9674	}
