 9882	        anyhow::bail!("mutant count must be 65, got {}", packet.mutants.len());
 9883	    }
 9884	    require_unique(packet.mutants.iter().map(|row| row.id.as_str()), "mutant")?;
 9885	    let requirement_ids = packet
 9886	        .requirements
 9887	        .iter()
 9888	        .map(|row| row.id.as_str())
 9889	        .collect::<BTreeSet<_>>();
 9890	    let mut by_family = BTreeMap::<&str, usize>::new();
 9891	    let mut by_operator = BTreeMap::<&str, usize>::new();
 9892	    for mutant in &packet.mutants {
 9893	        // M17.5 pass-2 #13: family/operator/source/disposition were free text,
 9894	        // so a fabricated inventory with invented labels was accepted whole.
 9895	        // Each must now name something this suite actually declares.
 9896	        if !MUTANT_FAMILIES.contains(&mutant.family.as_str()) {
 9897	            anyhow::bail!(
 9898	                "{} declares unknown mutation family {:?}; expected one of {:?}",
 9899	                mutant.id,
 9900	                mutant.family,
 9901	                MUTANT_FAMILIES
 9902	            );
 9903	        }
 9904	        if !MUTANT_OPERATORS.contains(&mutant.operator.as_str()) {
 9905	            anyhow::bail!(
 9906	                "{} declares unknown mutation operator {:?}; expected one of {:?}",
 9907	                mutant.id,
 9908	                mutant.operator,
