10641	///
10642	/// `<` and `>` are required to be spaced. Rustfmt writes comparisons that way
10643	/// and generic parameters the other, and without the distinction every struct
10644	/// field holding a `BTreeMap<K, V>` reads as a comparison.
10645	/// Whether `trimmed` uses `||` as a disjunction rather than as a closure's
10646	/// empty parameter list. Blind pass 1 at `ec045588` (A04): `ok_or_else(|| {`
10647	/// carries a `||` that no short-circuit mutation can act on, and the
10648	/// precondition counted it — the same mistake as a pattern's `|`, one token
10649	/// wider. A disjunction has an operand to its left.
10650	fn has_disjunction(trimmed: &str) -> bool {
10651	    trimmed.match_indices("||").any(|(at, _)| {
10652	        trimmed[..at]
10653	            .trim_end()
10654	            .chars()
10655	            .next_back()
10656	            .is_some_and(|previous| previous.is_alphanumeric() || matches!(previous, '_' | ')'))
