10809	    let after = patch.after.as_str();
10810	    let inversion_pairs = [
10811	        ("==", "!="),
10812	        ("!=", "=="),
10813	        ("<=", ">"),
10814	        (">=", "<"),
10815	        ("<", ">="),
10816	        (">", "<="),
10817	        ("&&", "||"),
10818	        ("||", "&&"),
10819	        ("|", "&"),
10820	        ("true", "false"),
10821	        ("false", "true"),
10822	    ];
