10913	fn integer_delta(before: &str, after: &str) -> Option<i64> {
10914	    fn scan(text: &str) -> Option<(Vec<String>, Vec<i64>)> {
10915	        let mut chars = text.char_indices().peekable();
10916	        let mut parts = Vec::new();
10917	        let mut values = Vec::new();
10918	        let mut cursor = 0;
10919	        while let Some((index, ch)) = chars.next() {
10920	            let starts_integer = ch.is_ascii_digit()
10921	                || (ch == '-' && chars.peek().is_some_and(|(_, next)| next.is_ascii_digit()));
10922	            if !starts_integer {
10923	                continue;
10924	            }
10925	            let mut end = index + ch.len_utf8();
10926	            while let Some((next_index, next)) = chars.peek().copied() {
10927	                if !next.is_ascii_digit() {
10928	                    break;
10929	                }
10930	                chars.next();
10931	                end = next_index + next.len_utf8();
10932	            }
10933	            parts.push(text[cursor..index].to_owned());
10934	            values.push(text[index..end].parse().ok()?);
10935	            cursor = end;
10936	        }
10937	        parts.push(text[cursor..].to_owned());
10938	        Some((parts, values))
10939	    }
10940	
10941	    if let Some(suffix) = after.strip_prefix(before).map(str::trim) {
10942	        if suffix == "+ 1" || suffix == "+1" {
10943	            return Some(1);
10944	        }
10945	        if suffix == "- 1" || suffix == "-1" {
