10948	    }
10949	    let (before_parts, before_values) = scan(before)?;
10950	    let (after_parts, after_values) = scan(after)?;
10951	    if before_parts != after_parts || before_values.len() != after_values.len() {
10952	        return None;
10953	    }
10954	    let mut delta = None;
10955	    for (before, after) in before_values.into_iter().zip(after_values) {
10956	        let change = after - before;
10957	        if change == 0 {
10958	            continue;
10959	        }
10960	        if delta.replace(change).is_some() || !matches!(change, 1 | -1) {
10961	            return None;
10962	        }
10963	    }
