 9379	fn verify_packet_shape(packet: &Packet) -> Result<()> {
 9380	    require_eq(
 9381	        "suite_version",
 9382	        &packet.suite_version,
 9383	        "phase1-haqp1-proposed-v2-seven-fuzz",
 9384	    )?;
 9385	    require_eq("status", &packet.status, "proposed")?;
 9386	    require_eq("ratification", &packet.ratification, "unratified")?;
 9387	    anyhow::ensure!(
 9388	        matches!(
 9389	            packet.concurrent_code.as_str(),
 9390	            "deterministic_schedule_exploration" | "not_applicable"
 9391	        ),
 9392	        "concurrent_code must be deterministic_schedule_exploration or not_applicable"
 9393	    );
 9394	    if packet.locked_acceptance_corpora_touched {
 9395	        anyhow::bail!("locked_acceptance_corpora_touched must be false");
 9396	    }
 9397	    require_exact_ids(
 9398	        packet.requirements.iter().map(|row| row.id.as_str()),
 9399	        (1..=REQUIREMENT_COUNT).map(|idx| format!("P1-R{idx:03}")),
 9400	        "requirement",
 9401	    )?;
 9402	    require_unique(
 9403	        packet.requirements.iter().map(|row| row.id.as_str()),
 9404	        "requirement",
 9405	    )?;
 9406	    let authoritative = authoritative_requirement_map();
 9407	    anyhow::ensure!(
 9408	        packet.requirements.len() == authoritative.len(),
 9409	        "requirement inventory cardinality is not authoritative: got {}, expected {}",
 9410	        packet.requirements.len(),
 9411	        authoritative.len()
 9412	    );
 9413	    let requirement_ids = packet
 9414	        .requirements
 9415	        .iter()
 9416	        .map(|row| row.id.as_str())
 9417	        .collect::<BTreeSet<_>>();
 9418	    require_unique(packet.tests.iter().map(|row| row.id.as_str()), "test")?;
 9419	    // The inventory grows as evidence kinds are declared (M17.5 F-05): the IDs
 9420	    // must stay dense and sequential, but the COUNT is not frozen at 8 — that
 9421	    // ceiling was the mechanism that kept 36 requirements on 8 coarse tests.
 9422	    require_exact_ids(
 9423	        packet.tests.iter().map(|row| row.id.as_str()),
 9424	        (1..=packet.tests.len()).map(|idx| format!("P1-T{idx:02}")),
 9425	        "test",
 9426	    )?;
 9427	    let mut covered_requirements = BTreeSet::new();
 9428	    for test in &packet.tests {
 9429	        if test.requirements.is_empty() {
 9430	            anyhow::bail!("{} has no requirement mapping", test.id);
 9431	        }
 9432	        for requirement in &test.requirements {
 9433	            if !requirement_ids.contains(requirement.as_str()) {
 9434	                anyhow::bail!("{} references unknown requirement {}", test.id, requirement);
 9435	            }
 9436	            covered_requirements.insert(requirement.as_str());
 9437	        }
 9438	    }
 9439	    for requirement in &packet.requirements {
 9440	        // M17.5 pass-2 #12: the `critical` guard let a non-critical requirement
 9441	        // sit in the inventory forever with no test behind it, inflating the
 9442	        // requirement count without adding any evidence. Every declared
 9443	        // requirement must be mapped; criticality decides how MUCH evidence is
 9444	        // needed (see `verify_evidence_coverage`), not whether any is.
 9445	        if !covered_requirements.contains(requirement.id.as_str()) {
 9446	            anyhow::bail!(
 9447	                "requirement {} ({}) is not mapped to any test — an unmapped \
 9448	                 requirement counts toward the inventory while proving nothing",
 9449	                requirement.id,
 9450	                if requirement.critical {
 9451	                    "critical"
 9452	                } else {
 9453	                    "non-critical"
 9454	                }
 9455	            );
 9456	        }
 9457	        if requirement.kind.trim().is_empty() || requirement.source.trim().is_empty() {
 9458	            anyhow::bail!("requirement {} has empty kind/source", requirement.id);
 9459	        }
 9460	        if !REQUIREMENT_KINDS.contains(&requirement.kind.as_str()) {
 9461	            anyhow::bail!(
 9462	                "requirement {} has unknown kind {:?}; expected one of {:?}",
 9463	                requirement.id,
 9464	                requirement.kind,
 9465	                REQUIREMENT_KINDS
 9466	            );
 9467	        }
 9468	        if STATEFUL_REQUIREMENT_IDS.contains(&requirement.id.as_str()) && !requirement.stateful {
 9469	            anyhow::bail!(
 9470	                "requirement {} is stateful and must set stateful=true",
 9471	                requirement.id
 9472	            );
 9473	        }
 9474	        let (source_file, coordinate) = requirement
 9475	            .source
 9476	            .split_once(':')
 9477	            .with_context(|| format!("requirement {} source lacks coordinate", requirement.id))?;
 9478	        anyhow::ensure!(
 9479	            !source_file.trim().is_empty() && !coordinate.trim().is_empty(),
 9480	            "requirement {} source must contain file and coordinate",
 9481	            requirement.id
 9482	        );
 9483	        let expected = authoritative
 9484	            .get(requirement.id.as_str())
 9485	            .with_context(|| {
 9486	                format!(
 9487	                    "requirement {} is not in the closed authoritative registry",
 9488	                    requirement.id
 9489	                )
 9490	            })?;
 9491	        anyhow::ensure!(
 9492	            requirement.kind == expected.0
 9493	                && requirement.source == expected.1
 9494	                && requirement.critical == expected.2
 9495	                && requirement.stateful == expected.3,
 9496	            "requirement {} differs from closed authoritative registry",
 9497	            requirement.id
 9498	        );
 9499	    }
 9500	    verify_evidence_coverage(packet)?;
 9501	    verify_test_registry(packet)?;
 9502	    verify_mutant_inventory(packet)?;
 9503	    verify_kill_concentration(packet)?;
 9504	    verify_canary_inventory(packet)?;
 9505	    verify_generated_inventory(packet)?;
 9506	    verify_reviews_inventory(packet)?;
 9507	    verify_crash_boundary_inventory(packet)?;
 9508	    verify_crash_boundary_scope_shape(packet)?;
 9509	    Ok(())
 9510	}
