 9512	fn authoritative_requirement_map()
 9513	-> BTreeMap<&'static str, (&'static str, &'static str, bool, bool)> {
 9514	    AUTHORITATIVE_REQUIREMENTS
 9515	        .iter()
 9516	        .map(|(id, kind, source, critical, stateful)| (*id, (*kind, *source, *critical, *stateful)))
