 9520	/// Evidence kinds every applicable critical requirement must carry
 9521	/// (ADR-0020 §2: "positive, negative, malformed/adversarial, basis/provenance,
 9522	/// and deterministic-replay evidence").
 9523	const CORE_EVIDENCE: [&str; 5] = ["positive", "negative", "malformed", "basis", "replay"];
 9524	/// "Stateful laws also have injected-fault and idempotent-recovery evidence."
 9525	const STATEFUL_EVIDENCE: [&str; 2] = ["fault", "recovery"];
 9526	/// Requirement kinds are closed by the HAQP packet contract. An open kind
 9527	/// vocabulary lets a packet relabel a stateful requirement and evade its
 9528	/// fault/recovery evidence obligations (M17.5 P1-A04).
 9529	const REQUIREMENT_KINDS: [&str; 4] = ["law", "gate", "fault", "abuse"];
 9530	/// Current packet's stateful law is M20 D20.3. Keep the semantic coordinate
 9531	/// closed even if an attacker relabels its `kind` or drops its JSON marker.
 9532	const STATEFUL_REQUIREMENT_IDS: [&str; 1] = ["P1-R015"];
 9533	/// No single test may carry more than this share of the mutation denominator.
 9534	const MAX_KILL_SHARE: f64 = 0.25;
 9535	
 9536	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
 9537	/// covered. Every critical requirement must carry all five core evidence
 9538	/// kinds, and fault-class requirements must additionally carry injected-fault
 9539	/// and idempotent-recovery evidence.
 9540	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
 9541	    let known = CORE_EVIDENCE
 9542	        .iter()
 9543	        .chain(STATEFUL_EVIDENCE.iter())
 9544	        .copied()
 9545	        .collect::<BTreeSet<_>>();
 9546	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
 9547	    for test in &packet.tests {
 9548	        if test.evidence.is_empty() {
 9549	            anyhow::bail!("{} declares no evidence kind", test.id);
 9550	        }
 9551	        for kind in &test.evidence {
 9552	            if !known.contains(kind.as_str()) {
 9553	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
 9554	            }
 9555	        }
 9556	        for requirement in &test.requirements {
 9557	            covered
 9558	                .entry(requirement.as_str())
 9559	                .or_default()
 9560	                .extend(test.evidence.iter().map(String::as_str));
 9561	        }
 9562	    }
 9563	    for requirement in &packet.requirements {
 9564	        if !requirement.critical {
 9565	            continue;
 9566	        }
 9567	        let have = covered
 9568	            .get(requirement.id.as_str())
 9569	            .cloned()
 9570	            .unwrap_or_default();
 9571	        let mut needed = CORE_EVIDENCE.to_vec();
 9572	        if requirement.stateful || requirement.kind == "fault" {
 9573	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
 9574	        }
 9575	        let missing = needed
 9576	            .into_iter()
 9577	            .filter(|kind| !have.contains(kind))
 9578	            .collect::<Vec<_>>();
 9579	        if !missing.is_empty() {
 9580	            anyhow::bail!(
 9581	                "critical requirement {} ({}) is missing {} evidence",
 9582	                requirement.id,
 9583	                requirement.kind,
 9584	                missing.join(", ")
 9585	            );
 9586	        }
 9587	    }
 9588	    Ok(())
 9589	}
