 9599	fn verify_test_registry(packet: &Packet) -> Result<()> {
 9600	    let mut canonical = String::new();
 9601	    for test in &packet.tests {
 9602	        canonical.push_str(&test.id);
 9603	        canonical.push('\0');
 9604	        canonical.push_str(&test.name);
 9605	        canonical.push('\0');
 9606	        canonical.push_str(&test.requirements.join("\x1f"));
 9607	        canonical.push('\0');
