 9619	fn contains_exact_coordinate(text: &str, coordinate: &str) -> bool {
 9620	    text.match_indices(coordinate).any(|(start, _)| {
 9621	        let end = start + coordinate.len();
 9622	        !text[..start]
 9623	            .chars()
 9624	            .next_back()
 9625	            .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
 9626	            && !text[end..]
 9627	                .chars()
 9628	                .next()
 9629	                .is_some_and(|ch| ch.is_ascii_alphanumeric() || ch == ':')
 9630	    })
 9631	}
