 9978	/// operator over a quarter of the denominator, and every named operator
 9979	/// present (blind pass 1 at 5fb1b57, A04).
 9980	fn verify_mutation_plan_balance(
 9981	    by_family: &BTreeMap<&str, usize>,
 9982	    by_operator: &BTreeMap<&str, usize>,
 9983	) -> Result<()> {
 9984	    const REQUIRED_OPERATORS: [&str; 13] = [
 9985	        "predicate-deletion",
 9986	        "predicate-inversion",
 9987	        "threshold-plus-one",
 9988	        "threshold-minus-one",
 9989	        "missing-enum-dispatch",
 9990	        "success-error-substitution",
 9991	        "stale-basis-acceptance",
 9992	        "wrong-holder-selection",
 9993	        "skipped-durable-transition",
 9994	        "disabled-crash-point",
 9995	        "ordering-nondeterminism",
 9996	        "oracle-short-circuit",
 9997	        "broadened-allow-list",
 9998	    ];
 9999	    for (family, count) in by_family {
10000	        if *count != 13 {
10001	            anyhow::bail!("family {family} mutant count must be 13, got {count}");
10002	        }
10003	    }
10004	    for (operator, count) in by_operator {
10005	        if *count > 16 {
10006	            anyhow::bail!("operator {operator} supplies {count} mutants; max 16");
10007	        }
10008	    }
10009	    // Blind pass 1 at 5fb1b57 (A04): the tally only bounded operators that were
10010	    // PRESENT, so dropping one entirely — broadened-allow-list has a single
10011	    // mutant — left the plan short an operator ADR-0020 §3 names and nothing
10012	    // said so. The list is the ADR's, closed.
10013	    let missing = REQUIRED_OPERATORS
10014	        .into_iter()
10015	        .filter(|operator| !by_operator.contains_key(operator))
10016	        .collect::<Vec<_>>();
