10512	/// Every declared mutant's anchor line must be able to CARRY its operator
10513	/// (M17.5 F-33). Runs at every layer, including stage 1a, because an
10514	/// inapplicable mutant is a defect in the inventory, not in the evidence.
10515	/// The locked corpus must be reachable by exactly one name (M17.5 F-34 /
10516	/// blind pass 1 A07).
10517	///
10518	/// The corpus-access audit refuses a traced path containing `heldout` or
10519	/// `conformance/corpora`. That is substring matching on what the process SAW,
10520	/// so it catches direct access and nothing else: a symlink or a rename gives
10521	/// the same bytes a path the filter does not recognise, and the audit reports
10522	/// clean while the locked corpus was read.
10523	///
10524	/// Rather than try to canonicalize strace output after the fact — the symlink
10525	/// may not exist by verification time — the aliasing itself is made
10526	/// impossible. If the locked corpus has exactly one name, then matching that
10527	/// name is sufficient, and the existing filter becomes sound rather than
10528	/// lucky.
10529	fn verify_locked_corpus_has_no_aliases(root: &Utf8Path) -> Result<()> {
10530	    use std::os::unix::fs::MetadataExt as _;
10531	    let locked = root.join("conformance/corpora/heldout");
10532	    // M17.5 F-65: this returned Ok when the corpus was absent, and nothing
10533	    // else in the gate required it to exist — so a tree with the corpus
10534	    // deleted passed every corpus check vacuously while the packet went on
10535	    // declaring `locked_acceptance_corpora_touched: false`. Twenty-three files
10536	    // are tracked; absence is a broken tree, not an empty obligation.
10537	    anyhow::ensure!(
10538	        locked.is_dir(),
10539	        "{locked} is missing: the locked corpus cannot be shown untouched when it is not there"
10540	    );
10541	    // The identities are the HELD-OUT corpus's, not the whole corpora tree's,
10542	    // so a hard link from `heldout` into a sibling corpus is an alias too — it
10543	    // would let a read of that sibling touch held-out bytes while every path
10544	    // involved looks legitimate.
10545	    let identities = locked_corpus_identities(root, "conformance/corpora/heldout")?;
10546	    let canonical = fs::canonicalize(&locked)
10547	        .with_context(|| format!("{locked}: locked corpus must resolve"))?;
10548	    let mut aliases = Vec::new();
10549	    let mut stack = vec![root.to_owned()];
10550	    while let Some(dir) = stack.pop() {
10551	        // A directory this cannot read is a directory it cannot clear of
10552	        // aliases; the same silent skip was a hard-link bypass in F-64.
10553	        let entries = fs::read_dir(&dir)
10554	            .with_context(|| format!("{dir}: scan the tree for corpus aliases"))?;
10555	        for entry in entries.flatten() {
10556	            // Blind pass 1 at `2bba9071` (A07): this conversion failing used
10557	            // to `continue`, so a path that is not UTF-8 skipped the identity
10558	            // comparison — the one check that needs no path at all. It is
10559	            // optional now; only the symlink branch requires it.
10560	            let converted = Utf8PathBuf::from_path_buf(entry.path()).ok();
10561	            let name = converted
10562	                .as_ref()
10563	                .and_then(|path| path.file_name())
10564	                .unwrap_or_default();
10565	            if name == ".git" || name == "target" {
10566	                continue;
10567	            }
10568	            let Ok(meta) = entry.path().symlink_metadata() else {
10569	                continue;
10570	            };
10571	            // Blind pass 1 at `ec045588` (A08): only symlinks counted. A hard
10572	            // link is the alias no path reasoning sees, and one created
10573	            // outside a traced process leaves the trace naming an innocent
10574	            // path; if it is then removed, neither the lexical fragments nor
10575	            // the inode check can resolve it afterwards. An alias that still
10576	            // exists in the tree is found here, which is where it can be.
10577	            if meta.is_file() && identities.contains(&(meta.dev(), meta.ino())) {
10578	                // A file inside the held-out corpus is the corpus rather than
10579	                // an alias to it. A path that is not UTF-8 cannot be inside
10580	                // it, so it reads as outside — the conservative side.
10581	                let inside = converted
10582	                    .as_ref()
10583	                    .is_some_and(|path| path.starts_with(&locked));
10584	                if !inside {
10585	                    aliases.push(entry.path().display().to_string());
10586	                    continue;
10587	                }
10588	            }
10589	            // The symlink branch needs the path itself; a non-UTF-8 one is
10590	            // already covered by the identity comparison above.
10591	            let Some(path) = converted else {
10592	                continue;
10593	            };
10594	            if meta.file_type().is_symlink() {
10595	                // A link INTO the locked tree gives its bytes a second name.
10596	                if let Ok(resolved) = fs::canonicalize(entry.path())
10597	                    && (resolved == canonical || resolved.starts_with(&canonical))
10598	                    && path != locked
10599	                {
10600	                    aliases.push(path.to_string());
10601	                }
10602	            } else if meta.is_dir() {
10603	                stack.push(path);
10604	            }
10605	        }
10606	    }
10607	    anyhow::ensure!(
10608	        aliases.is_empty(),
10609	        "the locked acceptance corpus is reachable under {} alias(es), so a traced \
10610	         path can read it without naming it: {aliases:?}",
10611	        aliases.len()
10612	    );
10613	    Ok(())
10614	}
