10824	        "predicate-inversion" => inversion_pairs.iter().any(|(from, to)| {
10825	            before.contains(from)
10826	                && after == before.replacen(from, to, 1)
10827	                && before.matches(from).count() == 1
10828	                && after.matches(to).count() >= 1
10829	        }),
10830	        "predicate-deletion" => before.contains('!') && after == before.replacen('!', "", 1),
