10833	        "missing-enum-dispatch" => before.contains("match") && !after.contains("match"),
10834	        "success-error-substitution" => {
10835	            (before.contains("Ok(") && after.contains("Err("))
10836	                || (before.contains("Err(") && after.contains("Ok("))
10837	        }
10838	        "oracle-short-circuit" => {
10839	            ((before.contains("&&") || before.contains("||"))
10840	                && (after.contains("return") || after.contains("Ok(")))
10841	                // P1-M012's closed anchor; exact replacements only.
10842	                || (before == "if id.is_some() {"
10843	                    && matches!(after, "if true {" | "if false {"))
