  9540	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
  9541	    let known = CORE_EVIDENCE
  9542	        .iter()
  9543	        .chain(STATEFUL_EVIDENCE.iter())
  9544	        .copied()
  9545	        .collect::<BTreeSet<_>>();
  9546	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
  9547	    for test in &packet.tests {
  9548	        if test.evidence.is_empty() {
  9549	            anyhow::bail!("{} declares no evidence kind", test.id);
  9550	        }
  9551	        for kind in &test.evidence {
  9552	            if !known.contains(kind.as_str()) {
  9553	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
  9554	            }
  9555	        }
  9556	        for requirement in &test.requirements {
  9557	            covered
  9558	                .entry(requirement.as_str())
  9559	                .or_default()
  9560	                .extend(test.evidence.iter().map(String::as_str));
  9561	        }
  9562	    }
  9563	    for requirement in &packet.requirements {
  9564	        if !requirement.critical {
  9565	            continue;
  9566	        }
  9567	        let have = covered
  9568	            .get(requirement.id.as_str())
  9569	            .cloned()
  9570	            .unwrap_or_default();
  9571	        let mut needed = CORE_EVIDENCE.to_vec();
  9572	        if requirement.stateful || requirement.kind == "fault" {
  9573	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
  9574	        }
  9575	        let missing = needed
  9576	            .into_iter()
  9577	            .filter(|kind| !have.contains(kind))
  9578	            .collect::<Vec<_>>();
  9579	        if !missing.is_empty() {
  9580	            anyhow::bail!(
  9581	                "critical requirement {} ({}) is missing {} evidence",
  9582	                requirement.id,
  9583	                requirement.kind,
