 10674	fn anchor_supports_operator(operator: &str, anchor: &str) -> bool {
 10675	    let trimmed = anchor.trim();
 10676	    let lower = trimmed.to_ascii_lowercase();
 10677	    let chars: Vec<char> = trimmed.chars().collect();
 10678	    let negation = chars.iter().enumerate().any(|(index, ch)| {
 10679	        *ch == '!'
 10680	            && chars.get(index + 1) != Some(&'=')
 10681	            && !index
 10682	                .checked_sub(1)
 10683	                .and_then(|prev| chars.get(prev))
 10684	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
 10685	    });
 10686	    let integer = chars.iter().enumerate().any(|(index, ch)| {
 10687	        ch.is_ascii_digit()
 10688	            && !index
 10689	                .checked_sub(1)
 10690	                .and_then(|prev| chars.get(prev))
 10691	                .is_some_and(|prev| prev.is_alphanumeric() || *prev == '_')
 10692	    });
 10693	    let word = |needle: &str| {
 10694	        trimmed
 10695	            .split(|ch: char| !ch.is_alphanumeric() && ch != '_')
 10696	            .any(|token| token == needle)
 10697	    };
 10698	    match operator {
 10699	        // `|` is one of the contract's inversion pairs and must stay, but only
 10700	        // when it occurs once: a closure's `|m| ...` has two, and a generic's
 10701	        // `<` is excluded by requiring spaces, because inverting the `<` of
 10702	        // `Vec<String>` yields `Vec>=String>`, which is not a program.
 10703	        "predicate-inversion" => {
 10704	            // Blind pass 1 at `0a0b4b4b` (A04): a `|` in a PATTERN is an
 10705	            // alternative, not an operator — inverting the bar of
 10706	            // `A | B => ...` yields `A & B`, which is not a pattern and does
 10707	            // not compile, so the mutant could never be applied let alone
 10708	            // killed. A bar counts only where it can be bitwise or.
 10709	            let pattern_alternative = trimmed.contains("=>") || trimmed.starts_with('|');
 10710	            [
 10711	                "==", "!=", " <= ", " >= ", " < ", " > ", "&&", " true", " false",
 10712	            ]
 10713	            .iter()
 10714	            .any(|token| trimmed.matches(token).count() == 1)
 10715	                || has_disjunction(trimmed)
 10716	                || (!pattern_alternative && trimmed.matches('|').count() == 1)
 10717	        }
 10718	        "predicate-deletion" => negation,
 10719	        "threshold-plus-one" | "threshold-minus-one" => integer,
 10720	        "missing-enum-dispatch" => word("match"),
 10721	        "success-error-substitution" => trimmed.contains("Ok(") || trimmed.contains("Err("),
 10722	        "oracle-short-circuit" => {
 10723	            trimmed.contains("&&") || has_disjunction(trimmed) || trimmed == "if id.is_some() {"
 10724	        }
 10725	        "ordering-nondeterminism" => {
 10726	            trimmed.contains("sort")
 10727	                || trimmed.contains("BTree")
 10728	                || trimmed.starts_with("let lines: Vec<")
 10729	        }
 10730	        "stale-basis-acceptance" => {
 10731	            lower.contains("basis") || trimmed == "if rev == inner.state.head {"
 10732	        }
 10733	        "skipped-durable-transition" => DURABLE_CALL_MARKERS
 10734	            .iter()
 10735	            .any(|call| trimmed.contains(call)),
 10736	        "disabled-crash-point" => {
 10737	            lower.contains("crash")
 10738	                || trimmed == "if fail_after.is_some_and(|limit| committed >= limit) {"
 10739	        }
 10740	        "broadened-allow-list" => {
 10741	            word("match")
 10742	                || trimmed.contains("matches!")
 10743	                || trimmed.contains("ensure!")
 10744	                || trimmed.contains("=>")
 10745	        }
 10746	        "wrong-holder-selection" => WRONG_HOLDER_ANCHORS.contains(&trimmed),
 10747	        _ => false,
 10748	    }
 10749	}
