 10752	    let mut inapplicable = Vec::new();
 10753	    for mutant in &packet.mutants {
 10754	        let Some((file, line)) = mutant.source.rsplit_once(':') else {
 10755	            anyhow::bail!("{} source {:?} is not file:line", mutant.id, mutant.source);
 10756	        };
 10757	        let line: usize = line
 10758	            .parse()
 10759	            .with_context(|| format!("{} source line {line:?} is not a number", mutant.id))?;
 10760	        let text = fs::read_to_string(root.join(file))
 10761	            .with_context(|| format!("{}: read anchor file {file}", mutant.id))?;
 10762	        let anchor = text
 10763	            .lines()
 10764	            .nth(line.saturating_sub(1))
 10765	            .with_context(|| format!("{} anchors {file}:{line}, past end of file", mutant.id))?;
 10766	        if line_is_inside_test_code(&text, line) {
 10767	            inapplicable.push(format!(
 10768	                "{} declares {:?} at {file}:{line}, which is inside test code: mutating an \
 10769	                 assertion measures the ORACLE, not the product",
 10770	                mutant.id, mutant.operator
