 10772	            continue;
 10773	        }
 10774	        if !anchor_supports_operator(&mutant.operator, anchor) {
 10775	            inapplicable.push(format!(
 10776	                "{} declares {:?} at {file}:{line}, whose text cannot be the BEFORE side of \
 10777	                 that operator's mutation: {:?}",
 10778	                mutant.id,
 10779	                mutant.operator,
