 10804	/// Require an evaluated patch to exhibit the lexical mutation prescribed by
 10805	/// its closed operator.  Anchoring and compilation alone allow an unrelated
 10806	/// replacement to masquerade as a predicate inversion.
 10807	fn verify_mutant_operator_patch(operator: &str, patch: &MutantPatch) -> Result<()> {
 10808	    let before = patch.before.as_str();
 10809	    let after = patch.after.as_str();
 10810	    let inversion_pairs = [
 10811	        ("==", "!="),
 10812	        ("!=", "=="),
 10813	        ("<=", ">"),
 10814	        (">=", "<"),
 10815	        ("<", ">="),
 10816	        (">", "<="),
 10817	        ("&&", "||"),
 10818	        ("||", "&&"),
 10819	        ("|", "&"),
 10820	        ("true", "false"),
 10821	        ("false", "true"),
 10822	    ];
 10823	    let recognized = match operator {
 10824	        "predicate-inversion" => inversion_pairs.iter().any(|(from, to)| {
 10825	            before.contains(from)
 10826	                && after == before.replacen(from, to, 1)
 10827	                && before.matches(from).count() == 1
 10828	                && after.matches(to).count() >= 1
 10829	        }),
 10830	        "predicate-deletion" => before.contains('!') && after == before.replacen('!', "", 1),
 10831	        "threshold-plus-one" => integer_delta(before, after) == Some(1),
 10832	        "threshold-minus-one" => integer_delta(before, after) == Some(-1),
 10833	        "missing-enum-dispatch" => before.contains("match") && !after.contains("match"),
 10834	        "success-error-substitution" => {
 10835	            (before.contains("Ok(") && after.contains("Err("))
 10836	                || (before.contains("Err(") && after.contains("Ok("))
 10837	        }
 10838	        "oracle-short-circuit" => {
 10839	            ((before.contains("&&") || before.contains("||"))
 10840	                && (after.contains("return") || after.contains("Ok(")))
 10841	                // P1-M012's closed anchor; exact replacements only.
 10842	                || (before == "if id.is_some() {"
 10843	                    && matches!(after, "if true {" | "if false {"))
 10844	        }
 10845	        "ordering-nondeterminism" => {
 10846	            ((before.contains("sort") || before.contains("BTree"))
 10847	                && (!after.contains("sort") || after.contains("Hash")))
 10848	                // P1-M011's closed anchor; require a Hash collection.
 10849	                || (before.starts_with("let lines: Vec<")
 10850	                    && before != after
 10851	                    && after.contains("Hash")
 10852	                    && !after.contains("let lines: Vec<"))
 10853	        }
 10854	        "stale-basis-acceptance" => {
 10855	            (before.to_ascii_lowercase().contains("basis")
 10856	                && !after.to_ascii_lowercase().contains("basis"))
 10857	                || (before == "if rev == inner.state.head {"
 10858	                    && matches!(after, "if true {" | "if false {"))
 10859	        }
 10860	        // M17.5 F-34 / blind pass 1 A11: this matched bare WORDS, so deleting
 10861	        // the token from a label satisfied it. The anchored site is
 10862	        // `self.commit_intent(id, intent, &format!("ack:{step_id}"), origin)?;`
 10863	        // — renaming the label from `ack:` to anything else "skipped a durable
 10864	        // transition" while commit_intent still ran and persistence was intact.
 10865	        //
