8122	fn corpus_identity_touched(root: &Utf8Path, paths: &BTreeSet<String>) -> Result<bool> {
8123	    use std::os::unix::fs::MetadataExt as _;
8124	    let identities = locked_corpus_identities(root, "conformance/corpora")?;
8125	    if identities.is_empty() {
8126	        return Ok(false);
