8117	/// Scan a scope's stored remainder and every carved part, binding each part's
8118	/// bytes to the digest the row declares. Returns the remainder's scan and the
8119	/// union of open paths; a locked-corpus fragment in ANY file is the row's.
8120	/// Whether any of `paths` names a file the locked corpus also names. A hard
8121	/// link is a second name for one inode, so no amount of path reasoning sees it.
8122	fn corpus_identity_touched(root: &Utf8Path, paths: &BTreeSet<String>) -> Result<bool> {
8123	    use std::os::unix::fs::MetadataExt as _;
8124	    let identities = locked_corpus_identities(root, "conformance/corpora")?;
8125	    if identities.is_empty() {
8126	        return Ok(false);
8127	    }
8128	    for path in paths {
8129	        let local = if Path::new(path).is_absolute() {
8130	            std::path::PathBuf::from(path)
8131	        } else {
8132	            root.as_std_path().join(path)
8133	        };
8134	        let resolved = canonicalize_trace_path(&local).unwrap_or(local);
8135	        if let Ok(metadata) = fs::symlink_metadata(&resolved)
8136	            && identities.contains(&(metadata.dev(), metadata.ino()))
8137	        {
8138	            return Ok(true);
8139	        }
8140	    }
8141	    Ok(false)
8142	}
