7687	/// `chdir("x") = 0` moves this pid; a failed chdir moves nothing, and a
7688	/// relative target moves it relative to where it already stood (A07).
7689	/// Give a line's relative paths the directory they were actually opened
7690	/// against: a directory fd if the call names one, else the pid's cwd (A07,
7691	/// A12). An absolute path is already anchored.
7692	fn anchor_relative_paths(
7693	    pid: u32,
7694	    open_fds: &BTreeMap<(u32, i64), String>,
7695	    cwds: &BTreeMap<u32, String>,
7696	    arguments: &mut [(String, bool, Option<i64>)],
7697	) {
7698	    // Each path is anchored against ITS OWN dirfd — `renameat`'s destination
7699	    // has a different one from its source — and falls back to the pid's cwd.
7700	    for (path, _, dirfd) in arguments.iter_mut() {
7701	        if path.starts_with('/') {
7702	            continue;
7703	        }
7704	        if let Some(base) = dirfd
7705	            .and_then(|fd| open_fds.get(&(pid, fd)))
7706	            .or_else(|| cwds.get(&pid))
7707	        {
7708	            *path = format!("{base}/{path}");
7709	        }
7710	    }
7711	}
