7713	/// The child pid a successful `clone`, `fork` or `vfork` line reports, if any.
7714	/// strace prints the new pid as the call's return value (A07).
7715	fn clone_child_pid(line: &str) -> Option<u32> {
7716	    let names = ["clone(", "clone3(", "fork(", "vfork("];
7717	    if !names.iter().any(|name| line.contains(name)) {
7718	        return None;
7719	    }
7720	    let child = line.rsplit(" = ").next()?.trim();
7721	    let child = child.split_whitespace().next()?;
7722	    child.parse::<u32>().ok().filter(|pid| *pid > 0)
7723	}
