7725	/// The (source, duplicate) descriptor pair a successful `dup`, `dup2`, `dup3`
7726	/// or `fcntl(F_DUPFD)` line reports (A07). strace prints the new descriptor as
7727	/// the return value.
7728	/// Blind pass 1 at 9eca4f0 (A07): only open-derived descriptors were tracked,
7729	/// so `dup`ing a locked directory fd and writing through the duplicate
7730	/// anchored against nothing. A duplicate names what its source named.
7731	fn record_duplicated_fd(
7732	    line: &str,
7733	    pid: u32,
7734	    returned_fd: Option<i64>,
7735	    open_fds: &mut BTreeMap<(u32, i64), String>,
7736	) {
7737	    if let Some((from, to)) = duplicated_fd(line, returned_fd)
7738	        && let Some(dir) = open_fds.get(&(pid, from)).cloned()
7739	    {
7740	        open_fds.insert((pid, to), dir);
7741	    }
7742	}
7743	
7744	fn duplicated_fd(line: &str, returned_fd: Option<i64>) -> Option<(i64, i64)> {
7745	    let to = returned_fd.filter(|fd| *fd >= 0)?;
7746	    let call = ["dup(", "dup2(", "dup3(", "fcntl("]
7747	        .into_iter()
7748	        .find(|name| line.contains(name))?;
7749	    if call == "fcntl(" && !line.contains("F_DUPFD") {
7750	        return None;
7751	    }
7752	    // strace prints these as `dup2(3, 7) = 7` — integer arguments only, so the
7753	    // first comma-separated piece is the source descriptor.
7754	    let args = line.split_once(call)?.1;
7755	    let from = args
7756	        .split(',')
7757	        .next()?
7758	        .trim_end_matches(')')
7759	        .trim()
7760	        .parse::<i64>()
7761	        .ok()?;
7762	    Some((from, to))
7763	}
