7801	/// The path an fd-only write syscall on `line` names, resolved through the
7802	/// descriptor map. Blind pass 1 at `ec045588` (A06): `chmod` names a path and
7803	/// was listed; `fchmod` names a descriptor and was not, so changing the locked
7804	/// corpus's mode through an open descriptor produced no write candidate.
7805	fn fd_write_target(
7806	    line: &str,
7807	    pid: u32,
7808	    open_fds: &BTreeMap<(u32, i64), String>,
7809	) -> Option<String> {
7810	    // Review of `f23bacd3`: a refused call changed nothing, and counting it
7811	    // would refuse a trace for a write that never happened. Every syscall in
7812	    // the table takes its descriptor first, which is what makes the first
7813	    // argument the fd.
7814	    if line.contains(" = -1 ") {
7815	        return None;
7816	    }
7817	    let call = FD_WRITE_SYSCALLS
7818	        .iter()
7819	        .find(|call| line.contains(**call))?;
7820	    let fd = line
7821	        .split_once(*call)?
7822	        .1
7823	        .split([',', ')'])
7824	        .next()?
7825	        .trim()
7826	        .parse::<i64>()
7827	        .ok()?;
7828	    open_fds.get(&(pid, fd)).cloned()
7829	}
