7993	/// Stream a stored trace, `.zst` accepted, without holding it whole.
7994	fn open_evidence_reader(path: &Utf8Path) -> Result<Box<dyn std::io::BufRead>> {
7995	    let file = fs::File::open(path).with_context(|| format!("open {path}"))?;
7996	    if path.extension() == Some("zst") {
7997	        let decoder = zstd::Decoder::new(file)
7998	            .with_context(|| format!("{path}: evidence is not valid zstd"))?;
7999	        // The decoder buffers its input; the outer BufReader is for read_until.
8000	        Ok(Box::new(std::io::BufReader::new(decoder)))
8001	    } else {
8002	        Ok(Box::new(std::io::BufReader::new(file)))
8003	    }
8004	}
