8104	/// whole trace (the carved fuzz binaries) or is a read the ruling permits.
8105	#[derive(Clone, Copy, PartialEq, Eq)]
8106	enum LockedCorpus {
8107	    AnyTouch,
8108	    WritesOnly,
8109	}
