8111	fn scan_scope_trace_file(path: &Utf8Path, label: &str) -> Result<ScopeTraceScan> {
8112	    let reader = open_evidence_reader(path)
8113	        .with_context(|| format!("{label}: captured scope trace is required"))?;
8114	    scan_scope_trace(reader).with_context(|| format!("{label}: {path}: scope trace unreadable"))
