8181	/// The fuzz scope's parts are exactly the campaign's per-target traces: every
8182	/// binary the stage tracer saw is judged, none twice, and no other scope carves.
8183	fn verify_scope_trace_parts(
8184	    row: &CorpusScopeTrace,
8185	    targets: &[CorpusAccessAuditTarget],
8186	) -> Result<()> {
8187	    let declared = row
8188	        .parts
8189	        .iter()
8190	        .map(|part| (part.trace.as_str(), part.trace_blake3.as_str()))
8191	        .collect::<BTreeSet<_>>();
8192	    anyhow::ensure!(
8193	        declared.len() == row.parts.len(),
8194	        "{} corpus scope declares a trace part twice",
8195	        row.scope
8196	    );
8197	    if row.scope == "fuzz" {
8198	        let expected = targets
8199	            .iter()
8200	            .map(|target| (target.trace.as_str(), target.trace_blake3.as_str()))
8201	            .collect::<BTreeSet<_>>();
8202	        anyhow::ensure!(
8203	            declared == expected,
8204	            "fuzz corpus scope parts differ from the campaign's per-target traces: \
8205	             declared={declared:?}, expected={expected:?}"
8206	        );
8207	    } else {
8208	        anyhow::ensure!(
