2339	fn verify_crash_rows(recorded: &CrashEvidence, declared: &BTreeSet<String>) -> Result<()> {
2340	    require_unique(
2341	        recorded.boundaries.iter().map(|row| row.boundary.as_str()),
2342	        "crash evidence boundary",
2343	    )?;
2344	    let evidenced = recorded
2345	        .boundaries
2346	        .iter()
2347	        .map(|row| row.boundary.clone())
2348	        .collect::<BTreeSet<_>>();
2349	    if declared != &evidenced {
2350	        anyhow::bail!(
2351	            "crash evidence covers different boundaries than the packet declares: \
2352	             packet={declared:?}, evidence={evidenced:?}"
2353	        );
2354	    }
2355	    let before = evidenced
2356	        .iter()
2357	        .filter(|boundary| boundary.contains("/before_"))
2358	        .count();
2359	    let after = evidenced
2360	        .iter()
2361	        .filter(|boundary| boundary.contains("/after_"))
2362	        .count();
2363	    anyhow::ensure!(
2364	        before > 0 && after > 0,
2365	        "crash evidence must identify both before-transition and after-transition boundaries"
2366	    );
2367	    for boundary in &evidenced {
2368	        anyhow::ensure!(
2369	            boundary.contains("/before_") || boundary.contains("/after_"),
2370	            "crash boundary {boundary:?} lacks an injection-side coordinate"
2371	        );
2372	    }
2373	    anyhow::ensure!(
2374	        recorded.registered == evidenced.len() && recorded.exercised == evidenced.len(),
2375	        "crash evidence registered/exercised counts do not match evidenced boundary count"
2376	    );
2377	    // ADR-0020 §5: runtime discovery and declared inventory must match exactly,
2378	    // and drift on EITHER side fails.
2379	    if recorded.registered != recorded.exercised {
2380	        anyhow::bail!(
2381	            "crash evidence records {} registered boundaries but {} exercised — an \
2382	             unexercised boundary is indistinguishable from a dead one",
2383	            recorded.registered,
2384	            recorded.exercised
2385	        );
2386	    }
2387	    verify_crash_scenario_coverage(recorded, declared)?;
2388	    for row in &recorded.boundaries {
2389	        if row.occurrences_exercised == 0 {
2390	            anyhow::bail!("crash boundary {} was never exercised", row.boundary);
2391	        }
2392	        anyhow::ensure!(
2393	            row.injected,
2394	            "crash boundary {} has no measured injection receipt",
2395	            row.boundary
2396	        );
2397	        if row.result != "pass" {
2398	            anyhow::bail!(
