2416	/// Packet booleans describe both sides of each durable transition. Bind them
2417	/// to measured evidence rows, rather than accepting packet-controlled claims
2418	/// that the runner injected both sides (P1-A12).
2419	fn verify_crash_injection_bindings(packet: &Packet, recorded: &CrashEvidence) -> Result<()> {
2420	    // verify_crash_rows already enforces exact packet/evidence boundary-set
2421	    // equality. This second pass binds each packet before/after boolean to the
2422	    // measured injection receipt for its closed authoritative pair.
2423	    let measured = recorded
2424	        .boundaries
2425	        .iter()
2426	        .map(|row| (row.boundary.as_str(), row.injected))
2427	        .collect::<BTreeMap<_, _>>();
2428	    for declaration in &packet.crash_boundaries {
2429	        let (before, after) = crash_injection_pair(&declaration.boundary).with_context(|| {
2430	            format!(
2431	                "crash boundary {:?} lacks closed before/after pair",
2432	                declaration.boundary
2433	            )
2434	        })?;
2435	        let measured_before = measured.get(before).copied().unwrap_or(false);
2436	        let measured_after = measured.get(after).copied().unwrap_or(false);
2437	        anyhow::ensure!(
2438	            declaration.before == measured_before,
2439	            "crash boundary {} before injection claim differs from measured evidence",
2440	            declaration.boundary
2441	        );
2442	        anyhow::ensure!(
2443	            declaration.after == measured_after,
2444	            "crash boundary {} after injection claim differs from measured evidence",
2445	            declaration.boundary
2446	        );
2447	    }
2448	    Ok(())
2449	}
2450	
2451	/// Closed pair registry. `after_finalize_before_notify` is intentionally not
2452	/// a mechanical `after_finalize` spelling; reconstructing names from packet
2453	/// prose caused P1-A12 to evade the finalization-after side.
2454	fn crash_injection_pair(boundary: &str) -> Option<(&'static str, &'static str)> {
2455	    match boundary {
2456	        "ilrp/before_intent_commit" | "ilrp/after_intent_commit" => {
2457	            Some(("ilrp/before_intent_commit", "ilrp/after_intent_commit"))
2458	        }
2459	        "ilrp/before_external_apply" | "ilrp/after_external_apply" => {
2460	            Some(("ilrp/before_external_apply", "ilrp/after_external_apply"))
2461	        }
2462	        "ilrp/before_ack" | "ilrp/after_ack" => Some(("ilrp/before_ack", "ilrp/after_ack")),
2463	        "ilrp/before_finalize" | "ilrp/after_finalize_before_notify" => {
2464	            Some(("ilrp/before_finalize", "ilrp/after_finalize_before_notify"))
2465	        }
2466	        _ => None,
2467	    }
2468	}
