13629	/// Write a scratch copy of a retained executable, keeping it executable.
13630	///
13631	/// `fs::write` creates mode 0644. The sanitizer proof verifier EXECUTES the
13632	/// binary for its runtime probe, so a copy written that way fails with "execute
13633	/// sanitizer runtime probe" before any property of the binary is examined. C27
13634	/// never noticed because its mutated binary was refused at the marker check,
13635	/// before execution; checking the unmutated baseline (F-87) is the first time a
13636	/// scratch copy had to run.
13637	fn write_executable(path: &Utf8Path, bytes: &[u8]) -> Result<()> {
13638	    fs::write(path, bytes).with_context(|| format!("write {path}"))?;
13639	    #[cfg(unix)]
13640	    {
13641	        use std::os::unix::fs::PermissionsExt;
13642	        fs::set_permissions(path, fs::Permissions::from_mode(0o755))
13643	            .with_context(|| format!("make {path} executable"))?;
13644	    }
13645	    Ok(())
13646	}
