13656	        .find(|row| row.sanitizer_proof.is_some())
13657	        .context("sanitizer canary requires retained sanitizer proof")?;
13658	    let mut proof = row
13659	        .sanitizer_proof
13660	        .clone()
13661	        .context("sanitizer canary requires retained sanitizer proof")?;
13662	    let scratch = liminal_scratch::ScratchDir::new("haq-sanitizer-canary")?;
13663	    let scratch_root = scratch.path();
13664	    // ScratchDir is fresh and private to this canary. Reject path escapes
13665	    // before reading committed artifacts or creating any scratch entry.
13666	    for (path, label) in [
13667	        (&proof.binary, "sanitizer canary binary"),
13668	        (&proof.runtime_probe, "sanitizer canary probe"),
13669	        (&proof.build_log, "sanitizer canary build log"),
13670	    ] {
13671	        let candidate = Utf8Path::new(path);
13672	        anyhow::ensure!(
13673	            !candidate.is_absolute()
13674	                && !candidate
13675	                    .components()
13676	                    .any(|part| part == camino::Utf8Component::ParentDir)
