13682	    let runtime_probe_path = safe_repo_path(root, &proof.runtime_probe, "sanitizer canary probe")?;
13683	    let build_log_path = safe_repo_path(root, &proof.build_log, "sanitizer canary build log")?;
13684	    let scratch_binary_path = scratch_root.join(&proof.binary);
13685	    let scratch_probe_path = scratch_root.join(&proof.runtime_probe);
