13648	/// Replace one retained sanitizer binary's runtime marker with inert bytes and
13649	/// invoke the same compiler/runtime proof verifier used by qualification. This
13650	/// keeps C27 tied to an executable artifact attack, not an in-memory boolean.
13651	fn run_sanitizer_canary(root: &Utf8Path) -> Result<()> {
13652	    let path = root.join("conformance/haqp/evidence/fuzz.json");
13653	    let rows: Vec<FuzzEvidence> = serde_json::from_slice(&fs::read(&path)?)?;
13654	    let row = rows
13655	        .iter()
13656	        .find(|row| row.sanitizer_proof.is_some())
13657	        .context("sanitizer canary requires retained sanitizer proof")?;
13658	    let mut proof = row
13659	        .sanitizer_proof
13660	        .clone()
13661	        .context("sanitizer canary requires retained sanitizer proof")?;
13662	    let scratch = liminal_scratch::ScratchDir::new("haq-sanitizer-canary")?;
13663	    let scratch_root = scratch.path();
13664	    // ScratchDir is fresh and private to this canary. Reject path escapes
13665	    // before reading committed artifacts or creating any scratch entry.
13666	    for (path, label) in [
13667	        (&proof.binary, "sanitizer canary binary"),
13668	        (&proof.runtime_probe, "sanitizer canary probe"),
13669	        (&proof.build_log, "sanitizer canary build log"),
13670	    ] {
13671	        let candidate = Utf8Path::new(path);
13672	        anyhow::ensure!(
13673	            !candidate.is_absolute()
13674	                && !candidate
13675	                    .components()
13676	                    .any(|part| part == camino::Utf8Component::ParentDir)
13677	                && !is_locked_acceptance_path(path),
13678	            "{label} path {path:?} escapes scratch evidence root"
13679	        );
13680	    }
13681	    let binary_path = safe_repo_path(root, &proof.binary, "sanitizer canary binary")?;
13682	    let runtime_probe_path = safe_repo_path(root, &proof.runtime_probe, "sanitizer canary probe")?;
13683	    let build_log_path = safe_repo_path(root, &proof.build_log, "sanitizer canary build log")?;
13684	    let scratch_binary_path = scratch_root.join(&proof.binary);
13685	    let scratch_probe_path = scratch_root.join(&proof.runtime_probe);
13686	    let scratch_log_path = scratch_root.join(&proof.build_log);
13687	    fs::create_dir_all(scratch_binary_path.parent().expect("binary parent"))?;
13688	    fs::create_dir_all(scratch_probe_path.parent().expect("probe parent"))?;
13689	    fs::create_dir_all(scratch_log_path.parent().expect("log parent"))?;
13690	    fs::copy(&runtime_probe_path, &scratch_probe_path)?;
13691	    fs::copy(&build_log_path, &scratch_log_path)?;
13692	    let mut binary = fs::read(&binary_path)?;
13693	    // F-87: the UNMUTATED proof must verify before the mutation is applied. A
13694	    // refusal is evidence about the marker only if nothing else was already
13695	    // refused. Without this, pinning the sanitizer toolchain (F-85) made the
13696	    // committed proof fail on its recorded `cargo +nightly` command, and C27
13697	    // went on reporting "caught" -- by the build-command check, not the
13698	    // runtime-marker check it exists to prove. This error deliberately does not
13699	    // match C27's declared prefix, so a baseline that does not verify is a
13700	    // missed canary, never a caught one.
13701	    write_executable(&scratch_binary_path, &binary)?;
13702	    verify_sanitizer_proof(scratch_root, row, &proof, None).map_err(|error| {
13703	        anyhow::anyhow!(
13704	            "sanitizer canary baseline does not verify, so no refusal can be attributed to \
13705	             the runtime marker: {error}"
13706	        )
13707	    })?;
13708	    let marker = match row.sanitizer.as_str() {
13709	        "address" | "leak" => b"asan_globals".as_slice(),
13710	        "memory" => b"msan".as_slice(),
13711	        "thread" => b"tsan".as_slice(),
13712	        _ => anyhow::bail!("unsupported sanitizer {}", row.sanitizer),
13713	    };
13714	    let mut replaced = false;
13715	    for offset in 0..=binary.len().saturating_sub(marker.len()) {
13716	        if &binary[offset..offset + marker.len()] == marker {
13717	            binary[offset..offset + marker.len()].fill(b'X');
13718	            replaced = true;
13719	        }
13720	    }
13721	    anyhow::ensure!(
13722	        replaced,
13723	        "sanitizer canary source binary has no runtime marker"
13724	    );
13725	    write_executable(&scratch_binary_path, &binary)?;
13726	    proof.binary_blake3 = hex_digest(&binary);
13727	    proof.runtime_probe_blake3 = hex_digest(&fs::read(&scratch_probe_path)?);
13728	    proof.build_log_blake3 = hex_digest(&fs::read(&scratch_log_path)?);
13729	    let error = verify_sanitizer_proof(scratch_root, row, &proof, None)
13730	        .expect_err("uninstrumented sanitizer canary must fail closed");
13731	    anyhow::bail!("sanitizer proof lacks compiler/runtime replay: {error}");
13732	}
