13312	/// Run one canary per DECLARED row, and require each row's prose to describe
13313	/// the mutation that was actually performed (M17.5 pass-2 #22).
13314	///
13315	/// The runner used to iterate a hardcoded canary range and read only
13316	/// `expected_failure`. `Canary.gate` and `Canary.violation` were therefore
13317	/// decorative: the packet could say C09 relabels a mutation family while the
13318	/// executed arm did something entirely different, and nothing would notice.
13319	/// That matters because the canary table is the artifact a reader trusts to
13320	/// learn WHAT the canaries prove — unverified prose in that position is
13321	/// worse than no prose, because it reads as evidence.
13322	///
13323	/// Driving the loop from `packet.canaries` rather than a hardcoded `1..=16`
13324	/// closes a drift hazard rather than a live hole: `verify_canary_inventory`
13325	/// currently pins the id set to exactly C01–C25, so an extra row is rejected
13326	/// before it reaches this function. But that rule is the only thing keeping the
13327	/// hardcoded range honest, and the natural future edit — relaxing it to a
13328	/// minimum when canary 17 is written — would have left the new canaries
13329	/// declared, counted, and never executed. The loop now cannot disagree with the
13330	/// table it reports on.
13331	fn run_canary_suite(
13332	    root: &Utf8Path,
13333	    baseline: &Packet,
13334	    markdown: &str,
13335	) -> Result<Vec<CanaryEvidence>> {
13336	    let baseline_digest = packet_digest(baseline)?;
13337	    let mut records = Vec::new();
13338	    for row in &baseline.canaries {
13339	        let mut packet = baseline.clone();
13340	        let mut altered_markdown = markdown.to_owned();
13341	        let performed = mutate_canary(
13342	            &row.id,
13343	            &mut packet,
13344	            &mut altered_markdown,
13345	            &baseline_digest,
13346	        )?;
13347	        require_eq(
13348	            &format!("{}.violation (packet prose vs executed mutation)", row.id),
13349	            &row.violation,
13350	            performed,
13351	        )?;
13352	        let observed = if is_qualification_canary(&row.id) {
13353	            run_qualification_canary(root, baseline, &row.id)
13354	                .expect_err("qualification canary must fail closed")
13355	                .to_string()
13356	        } else {
13357	            verify_packet_shape(&packet)
13358	                .and_then(|()| verify_packet_statuses(&packet, inventory_statuses()))
13359	                .and_then(|()| verify_markdown_surface_text(&altered_markdown, &packet))
13360	                .expect_err("mutated canary must fail closed")
13361	                .to_string()
13362	        };
13363	        if !canary_failure_matches(&row.expected_failure, &observed) {
13364	            anyhow::bail!(
13365	                "{}: expected failure {:?}, observed {observed:?}",
13366	                row.id,
13367	                row.expected_failure
13368	            );
13369	        }
13370	        let canonical = canary_expected_prefix(&row.id)?;
13371	        if let Some((_, phrase)) = CANARY_REQUIRED_PHRASE
13372	            .iter()
13373	            .find(|(id, _)| *id == row.id.as_str())
13374	        {
13375	            anyhow::ensure!(
13376	                row.expected_failure.contains(phrase),
13377	                "{}: expected failure {:?} must name the violation this canary performs \
13378	                 ({phrase:?}); its prefix is shared by every refusal of its kind",
13379	                row.id,
13380	                row.expected_failure
13381	            );
13382	        }
13383	        anyhow::ensure!(
13384	            row.expected_failure.starts_with(canonical),
13385	            "{}: expected failure {:?} is outside closed canary failure registry {:?}",
13386	            row.id,
13387	            row.expected_failure,
13388	            canonical
13389	        );
13390	        records.push(CanaryEvidence {
13391	            id: row.id.clone(),
13392	            gate: row.gate.clone(),
13393	            violation: row.violation.clone(),
13394	            expected_failure: row.expected_failure.clone(),
13395	            observed_failure: observed,
13396	            caught: true,
13397	            mutation_semantics: canary_mutation_semantics(&row.id)?.to_owned(),
