 10752	    let mut inapplicable = Vec::new();
 10753	    for mutant in &packet.mutants {
 10754	        let Some((file, line)) = mutant.source.rsplit_once(':') else {
 10755	            anyhow::bail!("{} source {:?} is not file:line", mutant.id, mutant.source);
