 10758	            .parse()
 10759	            .with_context(|| format!("{} source line {line:?} is not a number", mutant.id))?;
 10760	        let text = fs::read_to_string(root.join(file))
 10761	            .with_context(|| format!("{}: read anchor file {file}", mutant.id))?;
 10762	        let anchor = text
 10763	            .lines()
 10764	            .nth(line.saturating_sub(1))
 10765	            .with_context(|| format!("{} anchors {file}:{line}, past end of file", mutant.id))?;
 10766	        if line_is_inside_test_code(&text, line) {
