 11593	/// is a declaration, not a substring, so it is parsed as one.
 11594	fn markdown_header<'a>(text: &'a str, key: &str) -> Option<&'a str> {
 11595	    text.lines()
 11596	        .take_while(|line| !line.starts_with('#') || line.starts_with("# "))
