14818	/// Independent oracle for the interchange codec: structural round-trip,
14819	/// byte-stable re-encoding, and the promised shape counted in the encoded JSON
14820	/// by a parser that is not the codec (serde_json::Value), so a codec that
14821	/// silently dropped an operation could not certify itself.
14822	fn independent_oracle_interchange(
14823	    txn: &liminal_graph::Transaction,
14824	    decoded: &liminal_graph::Transaction,
14825	    once: &[u8],
14826	    twice: &[u8],
14827	    shape: InterchangeShape,
14828	) -> Result<Vec<u8>> {
14829	    // Do not serialize both sides with the product codec and compare those
14830	    // values. A serde field mutation would normalize expected and observed in
14831	    // the same way and make its own defect invisible (A02). Compare the
14832	    // decoded value through its public fields instead.
14833	    anyhow::ensure!(
14834	        txn.id == decoded.id,
14835	        "interchange field id changed during round trip"
14836	    );
14837	    anyhow::ensure!(
14838	        txn.parent == decoded.parent,
14839	        "interchange field parent changed during round trip"
14840	    );
14841	    anyhow::ensure!(
14842	        txn.meta.actor == decoded.meta.actor
14843	            && txn.meta.origin == decoded.meta.origin
14844	            && txn.meta.at == decoded.meta.at
14845	            && txn.meta.provenance == decoded.meta.provenance
14846	            && txn.meta.inverse == decoded.meta.inverse,
14847	        "interchange field meta changed during round trip"
14848	    );
14849	    anyhow::ensure!(
14850	        txn.ops.len() == decoded.ops.len(),
14851	        "interchange field ops length changed"
14852	    );
14853	    for (index, (expected, observed)) in txn.ops.iter().zip(&decoded.ops).enumerate() {
14854	        anyhow::ensure!(
14855	            expected == observed,
14856	            "interchange operation {index} changed during round trip"
14857	        );
14858	    }
14859	    anyhow::ensure!(once == twice, "interchange encoding is not byte-stable");
14860	    let value: serde_json::Value = serde_json::from_slice(once)?;
14861	    let ops = value["ops"]
14862	        .as_array()
14863	        .context("encoded transaction has no ops array")?;
14864	    let count = |key: &str| ops.iter().filter(|op| op.get(key).is_some()).count();
14865	    anyhow::ensure!(
14866	        count("create-node") == shape.nodes && count("add-relation") == shape.relations,
14867	        "encoded shape differs from the category's promise: {shape:?}"
14868	    );
14869	    // Blind pass 1 at f360e90 (A02): a renamed field round-trips through the
14870	    // same serde on both sides. The published schema is a closed key set.
14871	    // Sorted on this side: the pin is "no field added, removed or renamed",
14872	    // not the encoder's key order.
14873	    let keys = |value: &serde_json::Value| -> Vec<String> {
14874	        let mut keys: Vec<String> = value
14875	            .as_object()
14876	            .map(|map| map.keys().cloned().collect())
14877	            .unwrap_or_default();
14878	        keys.sort_unstable();
14879	        keys
14880	    };
14881	    anyhow::ensure!(
14882	        keys(&value) == ["id", "meta", "ops", "parent"],
14883	        "encoded transaction keys are not the published schema: {:?}",
14884	        keys(&value)
14885	    );
14886	    for op in ops {
14887	        if let Some(node) = op.pointer("/create-node/node") {
14888	            anyhow::ensure!(
14889	                keys(node) == ["flags", "id", "kind", "payload", "revision"],
14890	                "encoded node keys are not the published schema: {:?}",
14891	                keys(node)
14892	            );
14893	        }
14894	        if let Some(relation) = op.pointer("/add-relation/relation") {
14895	            anyhow::ensure!(
14896	                keys(relation)
14897	                    == [
14898	                        "flags", "id", "kind", "payload", "requires", "revision", "source",
14899	                        "target"
14900	                    ],
14901	                "encoded relation keys are not the published schema: {:?}",
14902	                keys(relation)
14903	            );
14904	        }
14905	    }
14906	    let payload_bytes = ops
14907	        .iter()
14908	        .filter_map(|op| op.pointer("/create-node/node/payload/text"))
14909	        .filter_map(serde_json::Value::as_str)
14910	        .map(str::len)
14911	        .max()
14912	        .unwrap_or(0);
14913	    anyhow::ensure!(
14914	        payload_bytes >= shape.payload_bytes_at_least,
14915	        "encoded payload {payload_bytes} bytes is under the category's floor"
14916	    );
